"use client";

import React, { useState, useEffect } from "react";
import { AppCard } from "@/components/ui/AppCard";
import { AppBadge } from "@/components/ui/AppBadge";
import { AppButton } from "@/components/ui/AppButton";
import { AppInput } from "@/components/ui/AppInput";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import { useTheme } from "@/components/theme/ThemeProvider";
import { usePermissions } from "@/hooks/usePermissions";
import { AMCHistoryModal } from "@/components/amc/AMCHistoryModal";
import { AMCTransactionsTab } from "@/components/amc/AMCTransactionsTab";
import { AMCRenewalsTab } from "@/components/amc/AMCRenewalsTab";
import { AMCAllocationsTab } from "@/components/amc/AMCAllocationsTab";
import { AMCPaymentsTab } from "@/components/amc/AMCPaymentsTab";
import { createClient } from "@/utils/supabase/client";
import { saveAMCEntity, deleteAMCEntity } from "@/lib/actions/amc";
import { saveMasterEntity } from "@/lib/actions/masters";
import { FormMultiSelect } from "@/components/ui/FormMultiSelect";
import { MasterOptionsManager } from "@/components/shared/MasterOptionsManager";
import Link from "next/link";
import { 
  ShieldCheck, 
  Plus, 
  RefreshCw,
  AlertTriangle,
  X,
  CheckCircle2,
  Lock,
  Edit,
  Trash2,
  Calendar,
  DollarSign,
  User,
  Users,
  Paperclip,
  Download,
  Loader2,
  Clock,
  Eye,
  EyeOff,
  BarChart2,
  PieChart,
  Check,
  Settings
} from "lucide-react";
import { AppTable, AppTableHeader, AppTableBody, AppTableRow, AppTableHead, AppTableCell } from "@/components/ui/AppTable";


interface AttachmentEntry {
  id: string;
  docName: string;
  file: File | null;
}

interface SolutionLineItem {
  id: string;
  resolutionName: string;
  remark: string;
  qty: number;
  rate: number;
  cgstPercent: number;
  cgstAmount: number;
  sgstPercent: number;
  sgstAmount: number;
  igstPercent: number;
  igstAmount: number;
  discount: number;
  netAmount: number;
  renewalPeriodType?: string;
  customRenewalDate?: string;
}

export default function AMCPage() {
  const supabase = createClient();
  const { hasPermission, loading: permsLoading } = usePermissions();
  let isLightMode = false;
  try {
    const { theme } = useTheme();
    isLightMode = ["light-neumorphic", "pure-white", "pure-white-neumorphic", "amazon-prime-upi"].includes(theme);
  } catch (e) {}

  const [records, setRecords] = useState<any[]>([]);
  const [users, setUsers] = useState<any[]>([]);
  const [departments, setDepartments] = useState<any[]>([]);
  const [vendors, setVendors] = useState<any[]>([]);
  const [masterContractTypes, setMasterContractTypes] = useState<string[]>(['AMC', 'Subscription', 'Perpetual License', 'Other']);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [errorAlert, setErrorAlert] = useState<string | null>(null);
  const [successAlert, setSuccessAlert] = useState<string | null>(null);
  const [amcData, setAmcData] = useState<any[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  
  const [selectedHistoryId, setSelectedHistoryId] = useState<string | null>(null);
  const [editRecordId, setEditRecordId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("Master");
  const [mounted, setMounted] = useState(false);
  
  // Phase 1 Fields
  const [formSoftwareName, setFormSoftwareName] = useState("");
  const [formVendorId, setFormVendorId] = useState("");
  const [formContractType, setFormContractType] = useState("AMC");
  const [formPurchaseDate, setFormPurchaseDate] = useState("");
  const [formExpiryDate, setFormExpiryDate] = useState("");
  const [formCost, setFormCost] = useState("");
  const [formAssignedTo, setFormAssignedTo] = useState("");
  const [formDepartmentId, setFormDepartmentId] = useState("");
  const [formStatus, setFormStatus] = useState("Active");
  const [formNotes, setFormNotes] = useState("");

  const [formCurrency, setFormCurrency] = useState("INR");
  const [formTotalLicenses, setFormTotalLicenses] = useState("");
  const [formUsedLicenses, setFormUsedLicenses] = useState("");
  const [formCostPerLicense, setFormCostPerLicense] = useState("");
  const [formLicenseKey, setFormLicenseKey] = useState("");
  const [formPaymentTerms, setFormPaymentTerms] = useState("");
  const [formSupportTier, setFormSupportTier] = useState("");
  const [formSlaUptime, setFormSlaUptime] = useState("");
  const [formSlaTat, setFormSlaTat] = useState("");
  const [formCostCenterId, setFormCostCenterId] = useState("");
  const [formNotifyBeforeDays, setFormNotifyBeforeDays] = useState("30");
  const [showLicenseKey, setShowLicenseKey] = useState(false);

  const handleRevealLicenseKey = async () => {
    if (confirm("Are you sure you want to reveal the license key? This action will be logged.")) {
       setShowLicenseKey(true);
       if (editRecordId) {
          try {
            const { data: { user } } = await supabase.auth.getUser();
            if (user) {
               await supabase.from('amc_license_views').insert([{
                 amc_id: editRecordId,
                 user_id: user.id
               }]);
            }
          } catch(e) { console.error("Failed to log view", e); }
       }
    }
  };

  // Phase 2 Fields - Structured
  const [solutionLineItems, setSolutionLineItems] = useState<SolutionLineItem[]>([]);

  // Derive computed values dynamically during render instead of useEffect loops
  const computedTotalCost = solutionLineItems.length > 0 
    ? solutionLineItems.reduce((sum, i) => sum + i.netAmount, 0).toFixed(2)
    : formCost;

  const parsedTotalCost = parseFloat(computedTotalCost);
  const parsedLicenses = parseInt(formTotalLicenses);
  const computedCostPerLicense = (parsedLicenses > 0 && !isNaN(parsedTotalCost))
    ? (parsedTotalCost / parsedLicenses).toFixed(2)
    : formCostPerLicense;

  const [formPoNumber, setFormPoNumber] = useState("");
  const [formPoDate, setFormPoDate] = useState("");
  const [formPutToUseDate, setFormPutToUseDate] = useState("");
  const [formRenewalPeriodType, setFormRenewalPeriodType] = useState("");

  const handleRenewalChange = (periodType: string, baseDateStr: string) => {
    setFormRenewalPeriodType(periodType);
    if (periodType && periodType !== "Custom" && baseDateStr) {
      const d = new Date(baseDateStr);
      if (!isNaN(d.getTime())) {
        switch (periodType) {
          case "Yearly": d.setFullYear(d.getFullYear() + 1); break;
          case "Half-Yearly": d.setMonth(d.getMonth() + 6); break;
          case "Quarterly": d.setMonth(d.getMonth() + 3); break;
          case "Monthly": d.setMonth(d.getMonth() + 1); break;
        }
        d.setDate(d.getDate() - 1);
        setFormExpiryDate(d.toISOString().split('T')[0]);
      }
    }
  };

  
  const [vendorContactName, setVendorContactName] = useState("");
  const [vendorContactEmail, setVendorContactEmail] = useState("");
  const [vendorContactPhone, setVendorContactPhone] = useState("");
  
  const [taxGstNumber, setTaxGstNumber] = useState("");
  const [taxPanNumber, setTaxPanNumber] = useState("");
  
  const [bankName, setBankName] = useState("");
  const [bankAccountNo, setBankAccountNo] = useState("");
  const [bankIfsc, setBankIfsc] = useState("");
  const [bankBranch, setBankBranch] = useState("");
  const [bankState, setBankState] = useState("");
  const [bankCity, setBankCity] = useState("");
  
  const [formIndustryType, setFormIndustryType] = useState<string[]>([]);
  const [formVendorType, setFormVendorType] = useState<string[]>([]);
  
  const [masterIndustryTypes, setMasterIndustryTypes] = useState<any[]>([]);
  const [masterVendorTypes, setMasterVendorTypes] = useState<any[]>([]);

  const [manageModalType, setManageModalType] = useState<"industry" | "vendor" | null>(null);
  
  const [vendorAddrLine1, setVendorAddrLine1] = useState("");
  const [vendorAddrLine2, setVendorAddrLine2] = useState("");
  const [vendorAddrCity, setVendorAddrCity] = useState("");
  const [vendorAddrState, setVendorAddrState] = useState("");
  const [vendorAddrPincode, setVendorAddrPincode] = useState("");
  
  const [formMsmeNumber, setFormMsmeNumber] = useState("");
  const [formSpecifications, setFormSpecifications] = useState("");

  const INDIAN_STATES = [
    "Andaman and Nicobar Islands", "Andhra Pradesh", "Arunachal Pradesh", "Assam",
    "Bihar", "Chandigarh", "Chhattisgarh", "Dadra and Nagar Haveli and Daman and Diu",
    "Delhi", "Goa", "Gujarat", "Haryana", "Himachal Pradesh", "Jammu and Kashmir",
    "Jharkhand", "Karnataka", "Kerala", "Ladakh", "Lakshadweep", "Madhya Pradesh",
    "Maharashtra", "Manipur", "Meghalaya", "Mizoram", "Nagaland", "Odisha",
    "Puducherry", "Punjab", "Rajasthan", "Sikkim", "Tamil Nadu", "Telangana",
    "Tripura", "Uttar Pradesh", "Uttarakhand", "West Bengal"
  ];

  const [masterCities, setMasterCities] = useState<{id:string, state_name:string, city_name:string}[]>([]);

  // Attachments State
  const [attachments, setAttachments] = useState<AttachmentEntry[]>([]);
  const [existingAttachments, setExistingAttachments] = useState<any[]>([]);

  const handleAddCity = async (stateName: string, setter: (city: string) => void) => {
    if (!stateName) {
      alert("Please select a state first before adding a city.");
      return;
    }
    const newCity = prompt(`Enter new city name for ${stateName}:`);
    if (!newCity || !newCity.trim()) return;
    
    const cityName = newCity.trim();
    try {
      const { data, error } = await supabase.from('master_cities').insert({ state_name: stateName, city_name: cityName }).select().single();
      if (error) {
        if (error.code === '23505') {
           alert("City already exists in this state!");
           setter(cityName);
        } else throw error;
      }
      if (data) {
        setMasterCities(prev => [...prev, data]);
        setter(cityName);
      }
    } catch(e) {
      console.error(e);
      alert("Failed to add city.");
    }
  };

  const handleAddContractType = async () => {
    const newType = prompt("Enter new Contract Type:");
    if (!newType || !newType.trim()) return;
    const typeName = newType.trim();

    if (masterContractTypes.includes(typeName)) {
      alert("Contract Type already exists!");
      setFormContractType(typeName);
      return;
    }

    try {
      const { data, error } = await supabase.from('master_contract_types').insert({ name: typeName }).select().single();
      if (error) {
        if (error.code === '42P01') {
          // Table doesn't exist yet (migration pending)
          alert("Database migration for Contract Types is pending. Please run the migration first.");
        } else {
          alert("Failed to add Contract Type: " + error.message);
        }
        return;
      }
      setMasterContractTypes(prev => [...prev, typeName]);
      setFormContractType(typeName);
      setSuccessAlert(`Contract Type '${typeName}' added successfully.`);
    } catch(e) {
      console.error(e);
      alert("Failed to add Contract Type.");
    }
  };

  const formatFileName = (rawName: string) => {
    const match = rawName.match(/^\[(.*?)\]_[^_]+_(.*)$/);
    if (match) {
      return `${match[1]}: ${match[2]}`;
    }
    return rawName;
  };
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    setMounted(true);
    fetchDependencies();
    fetchRecords();
  }, []);

  const fetchDependencies = async () => {
    try {
      const [{ data: usersData }, { data: deptsData }, { data: citiesData }, { data: vendorsData }, { data: contractTypesData }, { data: indData }, { data: venData }] = await Promise.all([
        supabase.from("user_master").select("id, full_name, email").eq("is_active", true),
        supabase.from("departments").select("id, name").eq("is_active", true),
        supabase.from("master_cities").select("*").order("city_name"),
        supabase.from("vendor_master").select("*").order("name"),
        supabase.from("master_contract_types").select("name").eq("is_active", true).order("name"),
        supabase.from("master_industry_types").select("*").eq("is_active", true).order("name"),
        supabase.from("master_vendor_types").select("*").eq("is_active", true).order("name")
      ]);
      if (usersData) setUsers(usersData);
      if (deptsData) setDepartments(deptsData);
      if (citiesData) setMasterCities(citiesData);
      if (vendorsData) setVendors(vendorsData);
      if (contractTypesData) {
        const uniqueTypes = Array.from(new Set([
          ...contractTypesData.map(c => c.name),
          'AMC', 'Subscription', 'Perpetual License', 'Other'
        ]));
        setMasterContractTypes(uniqueTypes);
      }
      if (indData) setMasterIndustryTypes(indData);
      if (venData) setMasterVendorTypes(venData);
    } catch (e) {
      console.error("Failed to load dependencies", e);
    }
  };

  const fetchRecords = async () => {
    setLoading(true);
    setErrorAlert(null);
    try {
      const { data, error } = await supabase
        .from("software_amc")
        .select(`
          *,
          user_master:assigned_to (id, full_name, email),
          departments:department_id (id, name),
          vendor_master:vendor_id (id, name)
        `)
        .eq("is_deleted", false)
        .order("created_at", { ascending: false });

      if (error) throw error;
      setRecords(data || []);
    } catch (err: any) {
      setErrorAlert("Failed to load records. " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchAttachments = async (recordId: string) => {
    try {
      const { data, error } = await supabase.storage.from('amc-attachments').list(recordId);
      if (data) {
        setExistingAttachments(data.filter(f => f.name !== '.emptyFolderPlaceholder'));
      } else {
        setExistingAttachments([]);
      }
    } catch (e) {
      console.error("Could not fetch attachments");
    }
  };

  useEffect(() => {
    if (successAlert || errorAlert) {
      const timer = setTimeout(() => {
        setSuccessAlert(null);
        setErrorAlert(null);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [successAlert, errorAlert]);

  const resetForm = () => {
    setEditRecordId(null);
    setFormSoftwareName("");
    setFormVendorId("");
    setFormContractType("AMC");
    setFormPurchaseDate("");
    setFormExpiryDate("");
    setFormCost("");
    setFormAssignedTo("");
    setFormDepartmentId("");
    setFormStatus("Active");
    setFormNotes("");
    
    setFormCurrency("INR");
    setFormTotalLicenses("");
    setFormUsedLicenses("");
    setFormCostPerLicense("");
    setFormLicenseKey("");
    setFormPaymentTerms("");
    setFormSupportTier("");
    setFormSlaUptime("");
    setFormSlaTat("");
    setFormCostCenterId("");
    setFormNotifyBeforeDays("30");
    setShowLicenseKey(false);
    
    setSolutionLineItems([]);
    setFormPoNumber("");
    setFormPoDate("");
    setFormPutToUseDate("");
    setFormRenewalPeriodType("");
    
    setVendorContactName("");
    setVendorContactEmail("");
    setVendorContactPhone("");
    
    setTaxGstNumber("");
    setTaxPanNumber("");
    
    setBankName("");
    setBankAccountNo("");
    setBankIfsc("");
    setBankBranch("");
    setBankState("");
    setBankCity("");
    
    setFormIndustryType([]);
    setFormVendorType([]);
    
    setVendorAddrLine1("");
    setVendorAddrLine2("");
    setVendorAddrCity("");
    setVendorAddrState("");
    setVendorAddrPincode("");
    
    setFormMsmeNumber("");
    setFormSpecifications("");
    
    setAttachments([]);
    setExistingAttachments([]);
  };

  const handleVendorChange = (vendorId: string) => {
    setFormVendorId(vendorId);
    if (!vendorId) return;
    const vendor = vendors.find(v => v.id === vendorId);
    if (vendor) {
      setVendorContactName(vendor.contact_name || "");
      setVendorContactEmail(vendor.contact_email || "");
      setVendorContactPhone(vendor.phone || "");
      setVendorAddrLine1(vendor.address_line1 || "");
      setVendorAddrLine2(vendor.address_line2 || "");
      setVendorAddrCity(vendor.city || "");
      setVendorAddrState(vendor.state || "");
      setVendorAddrPincode(vendor.pincode || "");
      setTaxGstNumber(vendor.tax_gstin || "");
      setTaxPanNumber(vendor.tax_pan || "");
      setFormMsmeNumber(vendor.tax_code || "");
      setBankName(vendor.bank_name || "");
      setBankAccountNo(vendor.bank_account_number || "");
      setBankIfsc(vendor.bank_ifsc || "");
      setBankBranch(vendor.bank_branch || "");
      setBankState(vendor.bank_state || "");
      setBankCity(vendor.bank_city || "");
      setFormIndustryType(vendor.industry_type ? vendor.industry_type.split(",").map((s: string) => s.trim()) : []);
      setFormVendorType(vendor.vendor_type ? vendor.vendor_type.split(",").map((s: string) => s.trim()) : []);
    }
  };

  const openCreateModal = () => {
    resetForm();
    setShowModal(true);
  };

  const openEditModal = (rec: any) => {
    resetForm();
    setEditRecordId(rec.id);
    setFormSoftwareName(rec.software_name || "");
    setFormVendorId(rec.vendor_id || "");
    setFormContractType(rec.contract_type || "AMC");
    setFormPurchaseDate(rec.purchase_date || "");
    setFormExpiryDate(rec.expiry_date || "");
    setFormCost(rec.cost?.toString() || "");
    setFormAssignedTo(rec.assigned_to || "");
    setFormDepartmentId(rec.department_id || "");
    setFormStatus(rec.status || "Active");
    setFormNotes(rec.notes || "");

    setFormCurrency(rec.currency || "INR");
    setFormTotalLicenses(rec.total_licenses?.toString() || "");
    setFormUsedLicenses(rec.used_licenses?.toString() || "");
    setFormCostPerLicense(rec.cost_per_license?.toString() || "");
    setFormLicenseKey(rec.license_key || "");
    setFormPaymentTerms(rec.payment_terms || "");
    setFormSupportTier(rec.support_tier || "");
    setFormSlaUptime(rec.sla_uptime?.toString() || "");
    setFormSlaTat(rec.sla_tat || "");
    setFormCostCenterId(rec.cost_center_id || "");
    setFormNotifyBeforeDays(rec.notify_before_days?.toString() || "30");
    setShowLicenseKey(false);

    setSolutionLineItems(rec.solution_line_items || []);
    setFormPoNumber(rec.po_number || "");
    setFormPoDate(rec.po_date || "");
    setFormPutToUseDate(rec.put_to_use_date || "");
    setFormRenewalPeriodType(rec.renewal_period_type || "");
    
    setVendorContactName(rec.vendor_contact_json?.name || "");
    setVendorContactEmail(rec.vendor_contact_json?.email || "");
    setVendorContactPhone(rec.vendor_contact_json?.phone || "");
    
    setTaxGstNumber(rec.taxation_json?.gstNumber || "");
    setTaxPanNumber(rec.taxation_json?.panNumber || "");
    
    setBankName(rec.bank_details_json?.bankName || "");
    setBankAccountNo(rec.bank_details_json?.accountNo || "");
    setBankIfsc(rec.bank_details_json?.ifsc || "");
    setBankBranch(rec.bank_details_json?.branchName || "");
    setBankState(rec.bank_details_json?.state || "");
    setBankCity(rec.bank_details_json?.city || "");
    
    setFormIndustryType(rec.industry_type ? rec.industry_type.split(",").map((s: string) => s.trim()) : []);
    setFormVendorType(rec.vendor_type ? rec.vendor_type.split(",").map((s: string) => s.trim()) : []);
    
    setVendorAddrLine1(rec.vendor_address_json?.line1 || "");
    setVendorAddrLine2(rec.vendor_address_json?.line2 || "");
    setVendorAddrCity(rec.vendor_address_json?.city || "");
    setVendorAddrState(rec.vendor_address_json?.state || "");
    setVendorAddrPincode(rec.vendor_address_json?.pincode || "");
    
    setFormMsmeNumber(rec.msme_number || "");
    setFormSpecifications(rec.specifications || "");

    fetchAttachments(rec.id);
    setShowModal(true);
  };

  const handleLineItemChange = (id: string, field: keyof SolutionLineItem, value: any) => {
    setSolutionLineItems(prev => prev.map(item => {
      if (item.id === id) {
        const updated = { ...item, [field]: value };
        // Parse numerical values
        const qty = parseFloat(updated.qty.toString()) || 0;
        const rate = parseFloat(updated.rate.toString()) || 0;
        const base = qty * rate;
        
        const cgstPct = parseFloat(updated.cgstPercent.toString()) || 0;
        const sgstPct = parseFloat(updated.sgstPercent.toString()) || 0;
        const igstPct = parseFloat(updated.igstPercent.toString()) || 0;
        const discount = parseFloat(updated.discount.toString()) || 0;
        
        updated.cgstAmount = parseFloat((base * (cgstPct / 100)).toFixed(2));
        updated.sgstAmount = parseFloat((base * (sgstPct / 100)).toFixed(2));
        updated.igstAmount = parseFloat((base * (igstPct / 100)).toFixed(2));
        updated.netAmount = parseFloat((base + updated.cgstAmount + updated.sgstAmount + updated.igstAmount - discount).toFixed(2));
        
        return updated;
      }
      return item;
    }));
  };

  const addLineItem = () => {
    setFormRenewalPeriodType("Custom");
    setSolutionLineItems(prev => [
      ...prev,
      {
        id: Math.random().toString(36).substr(2, 9),
        resolutionName: "",
        remark: "",
        qty: 1,
        rate: 0,
        cgstPercent: 0,
        cgstAmount: 0,
        sgstPercent: 0,
        sgstAmount: 0,
        igstPercent: 0,
        igstAmount: 0,
        discount: 0,
        netAmount: 0,
        renewalPeriodType: "",
        customRenewalDate: ""
      }
    ]);
  };

  const removeLineItem = (id: string) => {
    setSolutionLineItems(prev => prev.filter(item => item.id !== id));
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formVendorId.trim()) {
      setErrorAlert("Provider / Vendor Name is mandatory.");
      return;
    }
    if (!formSoftwareName.trim()) {
      setErrorAlert("Software Name is mandatory.");
      return;
    }

    if (!formContractType) { setErrorAlert("Contract Type is mandatory."); return; }
    if (!formStatus) { setErrorAlert("Status is mandatory."); return; }
    if (!formPurchaseDate) { setErrorAlert("Purchase Date is mandatory."); return; }
    if (!formAssignedTo) { setErrorAlert("Assigned To (Owner) is mandatory."); return; }
    if (!formDepartmentId) { setErrorAlert("Department is mandatory."); return; }

    if (!vendorContactName.trim()) { setErrorAlert("Contact Name is mandatory. Please update the Vendor Master profile to include a Contact Name."); return; }
    if (!vendorContactEmail.trim()) { setErrorAlert("Contact Email is mandatory. Please update the Vendor Master profile to include a Contact Email."); return; }
    if (!vendorContactPhone.trim()) { setErrorAlert("Contact Phone / Ext is mandatory. Please update the Vendor Master profile to include a Phone Number."); return; }

    let finalLineItems = [...solutionLineItems];
    if (finalLineItems.length === 0) {
      finalLineItems = [{
        id: Math.random().toString(36).substr(2, 9),
        resolutionName: formSoftwareName,
        remark: formSpecifications || "",
        qty: formTotalLicenses ? parseInt(formTotalLicenses) : 1,
        rate: computedTotalCost ? (parseFloat(computedTotalCost) || 0) : 0,
        cgstPercent: 0,
        cgstAmount: 0,
        sgstPercent: 0,
        sgstAmount: 0,
        igstPercent: 0,
        igstAmount: 0,
        discount: 0,
        netAmount: computedTotalCost ? (parseFloat(computedTotalCost) || 0) : 0,
        renewalPeriodType: formRenewalPeriodType || "",
        customRenewalDate: ""
      }];
    }

    const payload = {
      software_name: formSoftwareName,
      solution_name: finalLineItems.map(item => item.resolutionName).filter(Boolean).join(", ") || null,
      vendor_id: formVendorId,
      contract_type: formContractType,
      purchase_date: formPurchaseDate || null,
      expiry_date: formExpiryDate || null,
      put_to_use_date: formPutToUseDate || null,
      renewal_period_type: formRenewalPeriodType || null,
      cost: computedTotalCost ? parseFloat(computedTotalCost) : null,
      assigned_to: formAssignedTo || null,
      department_id: formDepartmentId || null,
      status: formStatus,
      po_number: formPoNumber || null,
      po_date: formPoDate || null,
      industry_type: formIndustryType.length > 0 ? formIndustryType.join(", ") : null,
      vendor_type: formVendorType.length > 0 ? formVendorType.join(", ") : null,
      msme_number: formMsmeNumber || null,
      specifications: formSpecifications || null,
      notes: formNotes,
      
      currency: formCurrency,
      total_licenses: formTotalLicenses ? parseInt(formTotalLicenses) : null,
      used_licenses: formUsedLicenses ? parseInt(formUsedLicenses) : null,
      cost_per_license: computedCostPerLicense ? parseFloat(computedCostPerLicense) : null,
      license_key: formLicenseKey || null,
      payment_terms: formPaymentTerms || null,
      support_tier: formSupportTier || null,
      sla_uptime: formSlaUptime ? parseFloat(formSlaUptime) : null,
      sla_tat: formSlaTat || null,
      cost_center_id: formCostCenterId || null,
      notify_before_days: formNotifyBeforeDays ? parseInt(formNotifyBeforeDays) : 30,
      
      // JSON fields
      solution_line_items: finalLineItems,
      vendor_contact_json: {
        name: vendorContactName,
        email: vendorContactEmail,
        phone: vendorContactPhone
      },
      taxation_json: {
        gstNumber: taxGstNumber,
        panNumber: taxPanNumber
      },
      bank_details_json: {
        bankName,
        accountNo: bankAccountNo,
        ifsc: bankIfsc,
        branchName: bankBranch,
        state: bankState,
        city: bankCity
      },
      vendor_address_json: {
        line1: vendorAddrLine1,
        line2: vendorAddrLine2,
        city: vendorAddrCity,
        state: vendorAddrState,
        pincode: vendorAddrPincode
      }
    };

    setUploading(true);
    try {
      let currentEditId = editRecordId;

      if (editRecordId) {
        const res = await saveAMCEntity("software_amc", payload, editRecordId);
        if (!res.success) throw new Error(res.error);
        setSuccessAlert("Subscription updated successfully.");
      } else {
        const res = await saveAMCEntity("software_amc", payload);
        if (!res.success) throw new Error(res.error);
        currentEditId = res.data?.id;
        setSuccessAlert("Subscription created successfully.");
      }

      // Handle File Uploads
      if (attachments.length > 0 && currentEditId) {
        for (const entry of attachments) {
          if (!entry.file) continue;
          const safeDocName = (entry.docName || 'Document').replace(/[^a-zA-Z0-9 -]/g, '');
          const fileName = `${currentEditId}/[${safeDocName}]_${Math.random().toString(36).substring(2, 8)}_${entry.file.name}`;
          await supabase.storage.from('amc-attachments').upload(fileName, entry.file);
        }
      }

      setShowModal(false);
      fetchRecords();
    } catch (err: any) {
      setErrorAlert("Failed to save record: " + err.message);
    } finally {
      setUploading(false);
    }
  };

  const handleApprove = async (id: string, status: string) => {
    try {
      const res = await saveAMCEntity("software_amc", { approval_status: status }, id);
      if (!res.success) throw new Error(res.error);
      setSuccessAlert(`AMC marked as ${status}`);
      await fetchRecords();
    } catch (err: any) {
      setErrorAlert(`Failed to update status: ${err.message}`);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Are you sure you want to delete this record?")) return;
    try {
      const res = await deleteAMCEntity("software_amc", id, false);
      if (!res.success) throw new Error(res.error);
      setSuccessAlert("Record deleted.");
      fetchRecords();
    } catch (err: any) {
      alert("Error: " + err.message);
    }
  };

  const deleteAttachment = async (fileName: string) => {
    if (!editRecordId) return;
    if (!confirm("Remove this attachment?")) return;
    try {
      await supabase.storage.from('amc-attachments').remove([`${editRecordId}/${fileName}`]);
      fetchAttachments(editRecordId);
    } catch(e) {
      console.error(e);
    }
  };

  const filteredDataset = records.filter(r => 
    r.software_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    r.vendor_master?.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    r.solution_name?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (!mounted || permsLoading) {
    return (
      <div className="h-screen flex items-center justify-center">
        <div className="animate-spin h-8 w-8 border-2 border-theme-btn-primary border-t-transparent rounded-full" />
      </div>
    );
  }

  if (!hasPermission("AMC_VIEW")) {
    return (
      <div className="h-screen flex flex-col items-center justify-center text-muted">
        <Lock className="h-12 w-12 mb-4 opacity-50" />
        <h2 className="text-xl font-semibold text-muted">Access Denied</h2>
        <p className="text-sm mt-2">You do not have permission to view the AMC module.</p>
      </div>
    );
  }

  return (
    <PageContainer strict={true}>
      <PageHeader
        title="Annual Maintenance Contracts"
        description="Manage Software AMCs, Subscriptions, and Ownership Assignments."
        icon={<ShieldCheck className="h-6 w-6" />}
        actions={
          <>
            <Link href="/amc/reports">
              <AppButton variant="outline" size="sm" leftIcon={<PieChart className="h-3.5 w-3.5" />}>
                Reports
              </AppButton>
            </Link>
            <Link href="/amc/analytics">
              <AppButton variant="outline" size="sm" leftIcon={<BarChart2 className="h-3.5 w-3.5" />}>
                Analytics
              </AppButton>
            </Link>
            <AppButton variant="outline" size="sm" onClick={fetchRecords} leftIcon={<RefreshCw className={`h-3.5 w-3.5 ${loading ? 'animate-spin text-theme-icon' : ''}`} />}>
              Refresh
            </AppButton>
            {hasPermission("AMC_CREATE") && (
              <AppButton variant="primary" size="sm" onClick={openCreateModal} leftIcon={<Plus className="h-3.5 w-3.5" />}>
                Add Subscription
              </AppButton>
            )}
          </>
        }
      />

      {errorAlert && (
        <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/20 flex items-start gap-3 mb-4">
          <AlertTriangle className="h-4 w-4 text-rose-400 shrink-0 mt-0.5" />
          <div className="flex-1 text-xs text-rose-200">{errorAlert}</div>
        </div>
      )}

      {successAlert && (
        <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center gap-2 text-xs text-emerald-300 mb-4">
          <CheckCircle2 className="h-4 w-4 text-emerald-400" />
          <span>{successAlert}</span>
        </div>
      )}

      <AppCard className="flex-1 flex flex-col min-h-0 overflow-hidden">
        <div className="p-4 border-b border-border flex items-center justify-between">
          <div className="flex items-center gap-2">
            <AppInput 
              placeholder="Search software, provider, solution..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-80"
            />
          </div>
          <div className="text-xs text-muted">
            {filteredDataset.length} records found
          </div>
        </div>
        
        <div className="flex-1 overflow-auto">
          <AppTable className="w-full text-left border-collapse text-sm whitespace-nowrap">
            <AppTableHeader className={`sticky top-0 z-10 bg-surface`}>
              <AppTableRow>
                <AppTableHead className="p-3 font-medium text-muted border-b border-border">Software Name</AppTableHead>
                <AppTableHead className="p-3 font-medium text-muted border-b border-border">Solution Name</AppTableHead>
                <AppTableHead className="p-3 font-medium text-muted border-b border-border">Vendor</AppTableHead>
                <AppTableHead className="p-3 font-medium text-muted border-b border-border">Type</AppTableHead>
                <AppTableHead className="p-3 font-medium text-muted border-b border-border">Owner</AppTableHead>
                <AppTableHead className="p-3 font-medium text-muted border-b border-border">Expiry Date</AppTableHead>
                <AppTableHead className="p-3 font-medium text-muted border-b border-border">Approval</AppTableHead>
                <AppTableHead className="p-3 font-medium text-muted border-b border-border">Status</AppTableHead>
                <AppTableHead className="p-3 font-medium text-muted border-b border-border text-right">Actions</AppTableHead>
              </AppTableRow>
            </AppTableHeader>
            <AppTableBody>
              {filteredDataset.length === 0 ? (
                <AppTableRow>
                  <AppTableCell colSpan={8} className="p-8 text-center text-muted">
                    No subscriptions found.
                  </AppTableCell>
                </AppTableRow>
              ) : (
                filteredDataset.map((rec) => (
                  <AppTableRow key={rec.id} className={`border-b border-border transition-colors hover:bg-elevated`}>
                    <AppTableCell className="p-3 font-medium">{rec.software_name}</AppTableCell>
                    <AppTableCell className="p-3">{rec.solution_name || '-'}</AppTableCell>
                    <AppTableCell className="p-3">{rec.vendor_master?.name || '-'}</AppTableCell>
                    <AppTableCell className="p-3">
                      <AppBadge variant={rec.contract_type === 'AMC' ? 'accent' : rec.contract_type === 'Subscription' ? 'warning' : 'neutral'}>
                        {rec.contract_type}
                      </AppBadge>
                    </AppTableCell>
                    <AppTableCell className="p-3">
                      <div className="flex items-center gap-2">
                        <User className="h-3 w-3 text-muted" />
                        <span>{rec.user_master?.full_name || 'Unassigned'}</span>
                      </div>
                    </AppTableCell>
                    <AppTableCell className="p-3">
                      {rec.expiry_date ? (
                        <div className="flex items-center gap-2">
                          <Calendar className="h-3 w-3 text-muted" />
                          <span>{new Date(rec.expiry_date).toLocaleDateString()}</span>
                        </div>
                      ) : '-'}
                    </AppTableCell>
                    <AppTableCell className="p-3">
                      <AppBadge variant={rec.approval_status === 'Active' ? 'success' : rec.approval_status === 'Pending Approval' ? 'warning' : 'neutral'}>{rec.approval_status || 'Pending Approval'}</AppBadge>
                    </AppTableCell>
                    <AppTableCell className="p-3">
                      <AppBadge variant={rec.status === 'Active' ? 'success' : 'danger'}>{rec.status}</AppBadge>
                    </AppTableCell>
                    <AppTableCell className="p-3 text-right space-x-2">
                      {rec.approval_status === 'Pending Approval' && hasPermission("SUPER_ADMIN") && (
                        <>
                          <AppButton variant="ghost" size="sm" onClick={() => handleApprove(rec.id, 'Active')} className="text-emerald-500 hover:text-emerald-600 hover:bg-emerald-500/10">
                            Approve
                          </AppButton>
                          <AppButton variant="ghost" size="sm" onClick={() => handleApprove(rec.id, 'Rejected')} className="text-red-500 hover:text-red-600 hover:bg-red-500/10">
                            Reject
                          </AppButton>
                        </>
                      )}
                      <AppButton variant="ghost" size="sm" onClick={() => setSelectedHistoryId(rec.id)} title="View Audit History">
                        <Clock className="h-3.5 w-3.5 text-theme-icon" />
                      </AppButton>
                      {hasPermission("AMC_EDIT") && (
                        <AppButton variant="ghost" size="sm" onClick={() => openEditModal(rec)} title="Edit Record & Log Transactions">
                          <Edit className="h-3.5 w-3.5" />
                        </AppButton>
                      )}
                      {hasPermission("AMC_DELETE") && (
                        <AppButton variant="ghost" size="sm" onClick={() => handleDelete(rec.id)} className="text-red-500 hover:text-red-600 hover:bg-red-500/10">
                          <Trash2 className="h-3.5 w-3.5" />
                        </AppButton>
                      )}
                    </AppTableCell>
                  </AppTableRow>
                ))
              )}
            </AppTableBody>
          </AppTable>
        </div>
      </AppCard>

      {/* History Modal */}
      {selectedHistoryId && (
        <AMCHistoryModal 
          amcId={selectedHistoryId} 
          isLightMode={isLightMode} 
          onClose={() => setSelectedHistoryId(null)} 
        />
      )}

      {manageModalType && (
        <MasterOptionsManager 
          title={manageModalType === "industry" ? "Industry Types" : "Vendor Types"}
          tableName={manageModalType === "industry" ? "master_industry_types" : "master_vendor_types"}
          options={manageModalType === "industry" ? masterIndustryTypes : masterVendorTypes}
          onClose={() => setManageModalType(null)}
          onUpdate={fetchDependencies}
        />
      )}


      {/* Full-Screen Page View for Add/Edit */}
      {showModal && (
        <div className={`fixed inset-0 z-[100] flex flex-col animate-in slide-in-from-bottom-4 duration-300 bg-surface`}>
          <div className={`flex items-center justify-between p-6 border-b shrink-0 bg-surface border-border shadow-[var(--shadow-ambient)]`}>
            <div className="space-y-1">
              <h2 className="text-2xl font-bold text-theme-icon">{editRecordId ? "Manage Subscription Record" : "Add New Subscription"}</h2>
              <p className="text-sm text-muted">Manage the core software record, mid-year transactions, and renewals.</p>
            </div>
            <AppButton variant="secondary" onClick={() => setShowModal(false)} className="p-2 rounded-full hover:bg-red-500/10 text-muted hover:text-red-500 transition-colors">
              <X className="h-6 w-6" />
            </AppButton>
          </div>

          {editRecordId && (
            <div className={`p-4 border-b shrink-0 bg-surface/50 dark:bg-surface/50 border-border`}>
              <div className="flex gap-1.5 overflow-x-auto p-1.5 bg-surface/50 dark:bg-surface/30 border border-border/60 dark:border-white/5 rounded-xl w-max max-w-full shadow-sm">
                {['Master', 'Payments', 'Transactions', 'Renewals', 'Allocations'].map(tab => (
                  <button 
                    key={tab}
                    type="button"
                    onClick={() => setActiveTab(tab)}
                    className={`px-5 py-2 text-[13px] font-bold rounded-lg transition-all whitespace-nowrap outline-none flex items-center justify-center min-w-[120px] ${
                      activeTab === tab 
                        ? 'bg-surface dark:bg-surface text-theme-icon dark:text-theme-icon shadow-sm border border-border/50 dark:border-white/10' 
                        : 'text-muted hover:text-foreground dark:text-muted dark:hover:text-muted hover:bg-elevated/50 dark:hover:bg-surface/5 border border-transparent'
                    }`}
                  >
                    {tab}
                  </button>
                ))}
              </div>
            </div>
          )}
          
          <div className="flex-1 overflow-y-auto w-full max-w-[98%] mx-auto pb-32">
            <div className={activeTab === 'Master' ? 'block' : 'hidden'}>
              <form onSubmit={handleSave} className="p-6 md:p-8 space-y-12">
            
            {/* SECTION: GENERAL & CONTRACT DETAILS */}
            <div className={`p-6 rounded-2xl border bg-surface border-border shadow-[var(--shadow-ambient)]`}>
              <h4 className="text-base font-bold pb-4 mb-4 border-b border-border flex items-center gap-2">
                <span className="bg-theme-btn-primary text-white h-6 w-6 rounded flex items-center justify-center text-xs">1</span>
                General & Contract Details
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="space-y-2 lg:col-span-2">
                  <label className="text-sm font-bold text-muted uppercase">Provider / Vendor <span className="text-red-500">*</span></label>
                  <select value={formVendorId} onChange={(e) => handleVendorChange(e.target.value)} required className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                    <option value="">-- Select Vendor --</option>
                    {vendors.map(v => (
                      <option key={v.id} value={v.id}>{v.name}</option>
                    ))}
                  </select>
                </div>
                <div className="space-y-2 lg:col-span-2">
                  <label className="text-sm font-bold text-muted uppercase">Software Name <span className="text-red-500">*</span></label>
                  <AppInput value={formSoftwareName} onChange={(e) => setFormSoftwareName(e.target.value)} required placeholder="e.g., Salesforce Enterprise" className="h-11" />
                </div>
                <div className="lg:col-span-4 grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-muted uppercase mb-2 block">Contract Type <span className="text-red-500">*</span></label>
                    <div className="flex gap-2 h-11">
                      <select 
                        className={`flex-1 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}
                        value={formContractType}
                        onChange={e => setFormContractType(e.target.value)}
                      >
                        {masterContractTypes.map(type => (
                          <option key={type} value={type}>{type}</option>
                        ))}
                      </select>
                      <button 
                        type="button"
                        onClick={handleAddContractType}
                        className="w-11 h-11 flex items-center justify-center rounded-xl bg-theme-btn-primary text-white hover:bg-theme-btn-primary/90 transition-all flex-shrink-0"
                        title="Add Contract Type"
                      >
                        <Plus className="h-5 w-5" />
                      </button>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-muted uppercase">Status <span className="text-red-500">*</span></label>
                    <select value={formStatus} onChange={(e) => setFormStatus(e.target.value)} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                      <option value="Active">Active</option>
                      <option value="Expired">Expired</option>
                      <option value="Renewed">Renewed</option>
                      <option value="Cancelled">Cancelled</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-bold text-muted uppercase">Software / AMC Specification</label>
                    <AppInput value={formSpecifications} onChange={(e) => setFormSpecifications(e.target.value)} placeholder="Detailed requirements or specs..." className="h-11" />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Purchase Date <span className="text-red-500">*</span></label>
                  <AppInput type="date" value={formPurchaseDate} onChange={(e) => setFormPurchaseDate(e.target.value)} className="h-11" />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Put to Use Date</label>
                  <AppInput type="date" value={formPutToUseDate} onChange={(e) => {
                    setFormPutToUseDate(e.target.value);
                    if (formRenewalPeriodType) handleRenewalChange(formRenewalPeriodType, e.target.value);
                  }} className="h-11" />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Renewal Period</label>
                  <select value={formRenewalPeriodType} onChange={(e) => handleRenewalChange(e.target.value, formPutToUseDate)} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                    <option value="">-- Select --</option>
                    <option value="Yearly">Yearly</option>
                    <option value="Half-Yearly">Half-Yearly</option>
                    <option value="Quarterly">Quarterly</option>
                    <option value="Monthly">Monthly</option>
                    <option value="Custom">Custom</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Expiry Date</label>
                  <AppInput type="date" value={formExpiryDate} onChange={(e) => setFormExpiryDate(e.target.value)} className="h-11" />
                </div>
                <div className="space-y-2 lg:col-span-2">
                  <label className="text-sm font-bold text-muted uppercase">Assigned To (Owner) <span className="text-red-500">*</span></label>
                  <select value={formAssignedTo} onChange={(e) => setFormAssignedTo(e.target.value)} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                    <option value="">-- Select Owner --</option>
                    {users.map(u => <option key={u.id} value={u.id}>{u.full_name} ({u.email})</option>)}
                  </select>
                </div>
                <div className="space-y-2 lg:col-span-2">
                  <label className="text-sm font-bold text-muted uppercase">Department <span className="text-red-500">*</span></label>
                  <select value={formDepartmentId} onChange={(e) => setFormDepartmentId(e.target.value)} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                    <option value="">-- Select Department --</option>
                    {departments.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Cost Center</label>
                  <select value={formCostCenterId} onChange={(e) => setFormCostCenterId(e.target.value)} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                    <option value="">-- Select Cost Center --</option>
                    {departments.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Remind Before (Days)</label>
                  <AppInput type="number" value={formNotifyBeforeDays} onChange={(e) => setFormNotifyBeforeDays(e.target.value)} min="1" max="365" className="h-11" />
                </div>
              </div>
            </div>

            {/* SECTION: LICENSE & USAGE TRACKING */}
            <div className={`p-6 rounded-2xl border bg-surface border-border shadow-[var(--shadow-ambient)]`}>
              <h4 className="text-base font-bold pb-4 mb-4 border-b border-border flex items-center gap-2">
                <span className="bg-theme-btn-primary text-white h-6 w-6 rounded flex items-center justify-center text-xs">2</span>
                License & Usage Tracking
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Total Licenses Purchased</label>
                  <AppInput type="number" value={formTotalLicenses} onChange={(e) => setFormTotalLicenses(e.target.value)} placeholder="e.g., 50" min="0" className="h-11" />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Licenses In-Use</label>
                  <AppInput type="number" value={formUsedLicenses} onChange={(e) => setFormUsedLicenses(e.target.value)} placeholder="e.g., 42" min="0" className="h-11" />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Cost Per License</label>
                  <AppInput type="number" value={computedCostPerLicense} onChange={(e) => setFormCostPerLicense(e.target.value)} placeholder="Auto-calculated" readOnly className="h-11 opacity-70" />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">License Key</label>
                  <div className="relative">
                    <AppInput type={showLicenseKey ? "text" : "password"} value={formLicenseKey} onChange={(e) => setFormLicenseKey(e.target.value)} placeholder="Enter License Key" className="h-11 pr-10" />
                    {formLicenseKey && (
                      <AppButton variant="secondary" type="button" onClick={showLicenseKey ? () => setShowLicenseKey(false) : handleRevealLicenseKey} className="absolute right-3 top-2.5 text-muted hover:text-subtle">
                        {showLicenseKey ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                      </AppButton>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {/* SECTION: SLA & PAYMENT TERMS */}
            <div className={`p-6 rounded-2xl border bg-surface border-border shadow-[var(--shadow-ambient)]`}>
              <h4 className="text-base font-bold pb-4 mb-4 border-b border-border flex items-center gap-2">
                <span className="bg-theme-btn-primary text-white h-6 w-6 rounded flex items-center justify-center text-xs">3</span>
                SLA & Payment Terms
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Currency</label>
                  <select value={formCurrency} onChange={(e) => setFormCurrency(e.target.value)} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                    <option value="INR">INR (₹)</option>
                    <option value="USD">USD ($)</option>
                    <option value="EUR">EUR (€)</option>
                    <option value="GBP">GBP (£)</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Payment Terms</label>
                  <select value={formPaymentTerms} onChange={(e) => setFormPaymentTerms(e.target.value)} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                    <option value="">-- Select --</option>
                    <option value="100% Advance">100% Advance</option>
                    <option value="Net 15">Net 15</option>
                    <option value="Net 30">Net 30</option>
                    <option value="Net 45">Net 45</option>
                    <option value="Net 60">Net 60</option>
                    <option value="Quarterly">Quarterly Installments</option>
                    <option value="50% Advance, 50% Post-Deployment">50% Advance, 50% Post-Deployment</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Support Tier</label>
                  <select value={formSupportTier} onChange={(e) => setFormSupportTier(e.target.value)} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                    <option value="">-- Select --</option>
                    <option value="Standard Business Hours">Standard Business Hours</option>
                    <option value="Premium 24x5">Premium 24x5</option>
                    <option value="Enterprise 24x7">Enterprise 24x7</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Guaranteed Uptime (%)</label>
                  <AppInput type="number" step="0.01" value={formSlaUptime} onChange={(e) => setFormSlaUptime(e.target.value)} placeholder="e.g., 99.9" min="0" max="100" className="h-11" />
                </div>
                <div className="space-y-2 lg:col-span-2">
                  <label className="text-sm font-bold text-muted uppercase">Resolution TAT (Turnaround Time)</label>
                  <AppInput value={formSlaTat} onChange={(e) => setFormSlaTat(e.target.value)} placeholder="e.g., 4 Hours for P1, 24 Hours for P2" className="h-11" />
                </div>
              </div>
            </div>

            {/* SECTION: SOLUTION LINE ITEMS */}
            <div className={`p-6 rounded-2xl border overflow-hidden bg-surface border-border shadow-[var(--shadow-ambient)]`}>
              <div className="flex items-center justify-between pb-4 mb-4 border-b border-border">
                <h4 className="text-base font-bold flex items-center gap-2">
                  <span className="bg-theme-btn-primary text-white h-6 w-6 rounded flex items-center justify-center text-xs">4</span>
                  Solution Name & Line Items
                </h4>
                <AppButton type="button" variant="outline" size="sm" onClick={addLineItem} leftIcon={<Plus className="h-4 w-4" />}>
                  Add Line Item
                </AppButton>
              </div>
              
              <div className="overflow-x-auto pb-4">
                <AppTable className="w-full text-left text-sm whitespace-nowrap min-w-[1200px]">
                  <AppTableHeader>
                    <AppTableRow className="text-xs text-muted uppercase tracking-wider border-b border-border">
                      <AppTableHead className="pb-3 px-2 font-bold w-64">Resolution Name</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-48">Remark</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-32">Renewal Period</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-32">Renewal Date</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-20">Qty</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-28">Rate</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-32">CGST (%)</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-32">SGST (%)</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-32">IGST (%)</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-28">Discount</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-32 text-right">Net Amount</AppTableHead>
                      <AppTableHead className="pb-3 px-2 font-bold w-12"></AppTableHead>
                    </AppTableRow>
                  </AppTableHeader>
                  <AppTableBody>
                    {solutionLineItems.length === 0 ? (
                      <AppTableRow>
                        <AppTableCell colSpan={10} className="py-8 text-center text-muted italic">No line items added. Click "Add Line Item" to begin.</AppTableCell>
                      </AppTableRow>
                    ) : (
                      solutionLineItems.map((item, index) => (
                        <AppTableRow key={item.id} className="border-b border-border/50">
                          <AppTableCell className="py-2 px-1">
                            <AppInput value={item.resolutionName} onChange={(e) => handleLineItemChange(item.id, "resolutionName", e.target.value)} placeholder="Name" className="h-9 text-xs" />
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1">
                            <AppInput value={item.remark} onChange={(e) => handleLineItemChange(item.id, "remark", e.target.value)} placeholder="Remark" className="h-9 text-xs" />
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1">
                            <select value={item.renewalPeriodType || ""} onChange={(e) => handleLineItemChange(item.id, "renewalPeriodType", e.target.value)} className={`w-full h-9 px-2 rounded-lg text-xs transition-all focus:ring-2 outline-none bg-surface border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                              <option value="">-- Select --</option>
                              <option value="Yearly">Yearly</option>
                              <option value="Half-Yearly">Half-Yearly</option>
                              <option value="Quarterly">Quarterly</option>
                              <option value="Monthly">Monthly</option>
                              <option value="Custom">Custom</option>
                            </select>
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1">
                            {item.renewalPeriodType === "Custom" ? (
                              <AppInput type="date" value={item.customRenewalDate || ""} onChange={(e) => handleLineItemChange(item.id, "customRenewalDate", e.target.value)} className="h-9 text-xs" />
                            ) : (
                              <span className="text-muted text-xs">-</span>
                            )}
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1">
                            <AppInput type="number" value={item.qty} onChange={(e) => handleLineItemChange(item.id, "qty", e.target.value)} className="h-9 text-xs" min={1} />
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1">
                            <AppInput type="number" value={item.rate} onChange={(e) => handleLineItemChange(item.id, "rate", e.target.value)} className="h-9 text-xs" />
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1">
                            <div className="flex items-center gap-1">
                              <AppInput type="number" value={item.cgstPercent} onChange={(e) => handleLineItemChange(item.id, "cgstPercent", e.target.value)} className="h-9 text-xs w-16" placeholder="%" />
                              <span className="text-xs text-muted w-16 truncate">({item.cgstAmount.toFixed(2)})</span>
                            </div>
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1">
                            <div className="flex items-center gap-1">
                              <AppInput type="number" value={item.sgstPercent} onChange={(e) => handleLineItemChange(item.id, "sgstPercent", e.target.value)} className="h-9 text-xs w-16" placeholder="%" />
                              <span className="text-xs text-muted w-16 truncate">({item.sgstAmount.toFixed(2)})</span>
                            </div>
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1">
                            <div className="flex items-center gap-1">
                              <AppInput type="number" value={item.igstPercent} onChange={(e) => handleLineItemChange(item.id, "igstPercent", e.target.value)} className="h-9 text-xs w-16" placeholder="%" />
                              <span className="text-xs text-muted w-16 truncate">({item.igstAmount.toFixed(2)})</span>
                            </div>
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1">
                            <AppInput type="number" value={item.discount} onChange={(e) => handleLineItemChange(item.id, "discount", e.target.value)} className="h-9 text-xs" />
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1 text-right font-bold text-theme-icon">
                            {item.netAmount.toFixed(2)}
                          </AppTableCell>
                          <AppTableCell className="py-2 px-1 text-right">
                            <AppButton variant="secondary" type="button" onClick={() => removeLineItem(item.id)} className="p-1.5 rounded bg-red-500/10 text-red-500 hover:bg-red-500/20 transition-colors">
                              <X className="h-4 w-4" />
                            </AppButton>
                          </AppTableCell>
                        </AppTableRow>
                      ))
                    )}
                  </AppTableBody>
                  {solutionLineItems.length > 0 && (
                    <tfoot>
                      <AppTableRow>
                        <AppTableCell colSpan={8} className="py-4 text-right font-bold text-muted">Total Net Amount:</AppTableCell>
                        <AppTableCell className="py-4 px-1 text-right font-black text-lg text-emerald-500">
                          {solutionLineItems.reduce((sum, i) => sum + i.netAmount, 0).toFixed(2)}
                        </AppTableCell>
                        <AppTableCell></AppTableCell>
                      </AppTableRow>
                    </tfoot>
                  )}
                </AppTable>
              </div>
            </div>

            {/* SECTION: VENDOR DETAILS */}
            <div className={`p-6 rounded-2xl border bg-surface border-border shadow-[var(--shadow-ambient)]`}>
              <h4 className="text-base font-bold pb-4 mb-4 border-b border-border flex items-center gap-2">
                <span className="bg-theme-btn-primary text-white h-6 w-6 rounded flex items-center justify-center text-xs">5</span>
                Vendor & Contact Details
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                
                {/* Vendor Identity */}
                <div className="space-y-4 col-span-1 md:col-span-3">
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="space-y-2 col-span-2">
                      <label className="text-sm font-bold text-muted uppercase">Industry Type</label>
                      <div className="flex gap-2">
                        <FormMultiSelect 
                          options={masterIndustryTypes.map(i => ({ value: i.name, label: i.name }))}
                          selectedValues={formIndustryType}
                          onChange={(vals) => {
                            setFormIndustryType(vals);
                            // Only clear vendor types if they don't match the new industries
                            const validIndustryNames = new Set(vals);
                            const validVendorTypes = masterVendorTypes
                              .filter(v => validIndustryNames.has(v.industry_name))
                              .map(v => v.name);
                            setFormVendorType(formVendorType.filter(vt => validVendorTypes.includes(vt)));
                          }}
                          placeholder="Select Industries..."
                          className="flex-1"
                          disabled={!!formVendorId}
                        />
                        <AppButton type="button" disabled={!!formVendorId} variant="outline" onClick={async () => {
                          const newInd = prompt("Enter new Industry Type:");
                          if (newInd && newInd.trim()) {
                            await saveMasterEntity("master_industry_types", { name: newInd.trim() });
                            await fetchDependencies();
                            setFormIndustryType([...formIndustryType, newInd.trim()]);
                          }
                        }} className="h-11 w-11 px-0 shrink-0" title="Add New Industry">
                          <Plus className="h-4 w-4" />
                        </AppButton>
                        <AppButton type="button" disabled={!!formVendorId} variant="outline" onClick={() => setManageModalType("industry")} className="h-11 w-11 px-0 shrink-0 text-muted" title="Manage Industry Types">
                          <Settings className="h-4 w-4" />
                        </AppButton>
                      </div>
                    </div>
                    <div className="space-y-2 col-span-2">
                      <label className="text-sm font-bold text-muted uppercase">Vendor Type (Multi-Select)</label>
                      <div className="flex gap-2">
                        <div className="flex-1">
                          <FormMultiSelect 
                            options={masterVendorTypes
                              .filter(v => formIndustryType.length === 0 || formIndustryType.includes(v.industry_name))
                              .map(v => ({ value: v.name, label: `${v.name} (${v.industry_name})` }))}
                            selectedValues={formVendorType}
                            onChange={setFormVendorType}
                            placeholder={formIndustryType.length > 0 ? "Select Vendor Types..." : "Select Industry First"}
                            disabled={!!formVendorId || formIndustryType.length === 0}
                          />
                        </div>
                        {formIndustryType.length > 0 && (
                          <AppButton type="button" disabled={!!formVendorId} variant="outline" onClick={async () => {
                            let targetIndustry = formIndustryType[0];
                            if (formIndustryType.length > 1) {
                               const choice = prompt(`Which industry does this new Vendor Type belong to?\nAvailable: ${formIndustryType.join(", ")}`);
                               if (!choice || !formIndustryType.includes(choice.trim())) {
                                 alert("Invalid industry selected. Creation cancelled.");
                                 return;
                               }
                               targetIndustry = choice.trim();
                            }
                            const newVen = prompt(`Enter new Vendor Type for ${targetIndustry}:`);
                            if (newVen && newVen.trim()) {
                              await saveMasterEntity("master_vendor_types", { name: newVen.trim(), industry_name: targetIndustry });
                              await fetchDependencies();
                              setFormVendorType([...formVendorType, newVen.trim()]);
                            }
                          }} className="h-11 w-11 px-0 shrink-0" title="Add New Vendor Type">
                            <Plus className="h-4 w-4" />
                          </AppButton>
                        )}
                        <AppButton type="button" disabled={!!formVendorId} variant="outline" onClick={() => setManageModalType("vendor")} className="h-11 w-11 px-0 shrink-0 text-muted" title="Manage Vendor Types">
                          <Settings className="h-4 w-4" />
                        </AppButton>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Contact Person & Address */}
                <div className="col-span-1 md:col-span-3 space-y-4 pt-4 border-t border-border">
                  <h5 className="text-sm font-semibold text-theme-icon">Contact Person & Address</h5>
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-bold text-muted uppercase">Contact Name <span className="text-red-500">*</span></label>
                      <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70" : ""} value={vendorContactName} onChange={(e) => setVendorContactName(e.target.value)} placeholder="Full Name" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-bold text-muted uppercase">Contact Email <span className="text-red-500">*</span></label>
                      <AppInput type="email" readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70" : ""} value={vendorContactEmail} onChange={(e) => setVendorContactEmail(e.target.value)} placeholder="Email Address" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-bold text-muted uppercase">Address Line 1</label>
                      <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70" : ""} value={vendorAddrLine1} onChange={(e) => setVendorAddrLine1(e.target.value)} placeholder="Building, Street" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-bold text-muted uppercase">Address Line 2</label>
                      <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70" : ""} value={vendorAddrLine2} onChange={(e) => setVendorAddrLine2(e.target.value)} placeholder="Area, Landmark" />
                    </div>

                    <div className="space-y-2">
                      <label className="text-[10px] font-bold text-muted uppercase">Phone / Ext <span className="text-red-500">*</span></label>
                      <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70" : ""} value={vendorContactPhone} onChange={(e) => setVendorContactPhone(e.target.value)} placeholder="Contact Number" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-bold text-muted uppercase">State</label>
                      <select disabled={!!formVendorId} value={vendorAddrState} onChange={(e) => {
                        setVendorAddrState(e.target.value);
                        setVendorAddrCity(""); // Reset city when state changes
                      }} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none ${formVendorId ? "bg-surface opacity-70" : "bg-surface"} border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                        <option value="">Select State</option>
                        {INDIAN_STATES.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-bold text-muted uppercase flex items-center justify-between">
                        <span>City</span>
                        <AppButton variant="secondary" type="button" onClick={() => handleAddCity(vendorAddrState, setVendorAddrCity)} disabled={!!formVendorId} className="text-theme-icon hover:bg-theme-btn-primary/10 rounded-full p-0.5 transition-colors disabled:opacity-50" title="Add New City">
                          <Plus className="h-4 w-4" />
                        </AppButton>
                      </label>
                      <select value={vendorAddrCity} onChange={(e) => setVendorAddrCity(e.target.value)} disabled={!vendorAddrState || !!formVendorId} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none disabled:opacity-50 ${formVendorId ? "bg-surface opacity-70" : "bg-surface"} border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                        <option value="">Select City</option>
                        {masterCities.filter(c => c.state_name === vendorAddrState).map(c => <option key={c.id} value={c.city_name}>{c.city_name}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-bold text-muted uppercase">Pincode / Zip</label>
                      <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70" : ""} value={vendorAddrPincode} onChange={(e) => setVendorAddrPincode(e.target.value)} placeholder="Pincode" />
                    </div>
                  </div>
                </div>
                
              </div>
            </div>

            {/* SECTION: FINANCIALS */}
            <div className={`p-6 rounded-2xl border bg-surface border-border shadow-[var(--shadow-ambient)]`}>
              <h4 className="text-base font-bold pb-4 mb-4 border-b border-border flex items-center gap-2">
                <span className="bg-theme-btn-primary text-white h-6 w-6 rounded flex items-center justify-center text-xs">6</span>
                Financial & Taxation Details
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                
                {/* PO Details */}
                <div className="space-y-4">
                  <h5 className="text-sm font-semibold text-theme-icon">Purchase Order</h5>
                  <div className="space-y-3">
                    <div>
                      <label className="text-[10px] font-bold text-muted uppercase">PO Number</label>
                      <AppInput value={formPoNumber} onChange={(e) => setFormPoNumber(e.target.value)} placeholder="PO-..." />
                    </div>
                    <div>
                      <label className="text-[10px] font-bold text-muted uppercase">PO Date</label>
                      <AppInput type="date" value={formPoDate} onChange={(e) => setFormPoDate(e.target.value)} />
                    </div>
                    <div>
                      <label className="text-[10px] font-bold text-muted uppercase">
                        {solutionLineItems.length > 0 ? "Overall Cost (Auto-Calculated)" : "Manual Overall Cost (Legacy)"}
                      </label>
                      <div className="relative">
                        <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted" />
                        <AppInput 
                          type="number" 
                          step="0.01" 
                          value={computedTotalCost} 
                          onChange={(e) => setFormCost(e.target.value)} 
                          className="pl-9" 
                          placeholder="0.00" 
                          disabled={solutionLineItems.length > 0} 
                        />
                      </div>
                    </div>
                  </div>
                </div>

                {/* Taxation */}
                <div className="space-y-4">
                  <h5 className="text-sm font-semibold text-theme-icon">Taxation</h5>
                  <div className="space-y-3">
                    <div>
                      <label className="text-[10px] font-bold text-muted uppercase">GST Number</label>
                      <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70" : ""} value={taxGstNumber} onChange={(e) => setTaxGstNumber(e.target.value)} placeholder="GSTIN" />
                    </div>
                    <div>
                      <label className="text-[10px] font-bold text-muted uppercase">PAN Number</label>
                      <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70" : ""} value={taxPanNumber} onChange={(e) => setTaxPanNumber(e.target.value)} placeholder="PAN" />
                    </div>
                    <div>
                      <label className="text-[10px] font-bold text-muted uppercase">MSME Number</label>
                      <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70" : ""} value={formMsmeNumber} onChange={(e) => setFormMsmeNumber(e.target.value)} placeholder="MSME Reg. No." />
                    </div>
                  </div>
                </div>
              </div>

              {/* Bank Details Sub Section */}
              <div className="mt-8 pt-6 border-t border-border space-y-4">
                <h5 className="text-sm font-semibold text-theme-icon">Bank Details</h5>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-muted uppercase">Bank Name</label>
                    <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70 h-11" : "h-11"} value={bankName} onChange={(e) => setBankName(e.target.value)} placeholder="Bank Name" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-muted uppercase">Account Number</label>
                    <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70 h-11" : "h-11"} value={bankAccountNo} onChange={(e) => setBankAccountNo(e.target.value)} placeholder="Account No" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-muted uppercase">IFSC Code</label>
                    <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70 h-11" : "h-11"} value={bankIfsc} onChange={(e) => setBankIfsc(e.target.value)} placeholder="IFSC" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-muted uppercase">Branch Name</label>
                    <AppInput readOnly={!!formVendorId} className={formVendorId ? "bg-surface opacity-70 h-11" : "h-11"} value={bankBranch} onChange={(e) => setBankBranch(e.target.value)} placeholder="e.g., MG Road Branch" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-muted uppercase">State</label>
                    <select disabled={!!formVendorId} value={bankState} onChange={(e) => {
                      setBankState(e.target.value);
                      setBankCity(""); // Reset city
                    }} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none ${formVendorId ? "bg-surface opacity-70" : "bg-surface"} border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                      <option value="">Select State</option>
                      {INDIAN_STATES.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-muted uppercase flex items-center justify-between">
                      <span>City</span>
                      <AppButton variant="secondary" type="button" onClick={() => handleAddCity(bankState, setBankCity)} disabled={!!formVendorId} className="text-theme-icon hover:bg-theme-btn-primary/10 rounded-full p-0.5 transition-colors disabled:opacity-50" title="Add New City">
                        <Plus className="h-4 w-4" />
                      </AppButton>
                    </label>
                    <select value={bankCity} onChange={(e) => setBankCity(e.target.value)} disabled={!bankState || !!formVendorId} className={`w-full h-11 px-4 rounded-xl text-sm transition-all focus:ring-2 outline-none disabled:opacity-50 ${formVendorId ? "bg-surface opacity-70" : "bg-surface"} border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`}>
                      <option value="">Select City</option>
                      {masterCities.filter(c => c.state_name === bankState).map(c => <option key={c.id} value={c.city_name}>{c.city_name}</option>)}
                    </select>
                  </div>
                </div>
              </div>
            </div>

            {/* SECTION: ATTACHMENTS & MISC */}
            <div className={`p-6 rounded-2xl border bg-surface border-border shadow-[var(--shadow-ambient)]`}>
              <h4 className="text-base font-bold pb-4 mb-4 border-b border-border flex items-center gap-2">
                <span className="bg-theme-btn-primary text-white h-6 w-6 rounded flex items-center justify-center text-xs">7</span>
                Attachments & Notes
              </h4>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <div className="space-y-3">
                    <div className="flex items-center justify-between">
                      <label className="text-sm font-bold text-muted uppercase">Documents & Attachments</label>
                      <AppButton type="button" variant="outline" size="sm" onClick={() => {
                        setAttachments(prev => [...prev, { id: Math.random().toString(36).substring(2, 9), docName: "", file: null }]);
                      }} leftIcon={<Plus className="h-4 w-4" />}>
                        Add Document
                      </AppButton>
                    </div>
                    
                    <div className="space-y-3">
                      {attachments.map(entry => (
                        <div key={entry.id} className={`flex flex-col sm:flex-row sm:items-center gap-3 p-3 rounded-xl border bg-elevated border-border`}>
                          <select 
                            value={entry.docName} 
                            onChange={(e) => setAttachments(prev => prev.map(a => a.id === entry.id ? { ...a, docName: e.target.value } : a))}
                            className={`w-full sm:w-48 h-10 px-3 rounded-lg text-sm border outline-none focus:ring-2 focus:ring-theme-btn-primary/20 bg-surface border-border text-foreground`}
                          >
                            <option value="">Select Type</option>
                            <option value="SOP Document">SOP Document</option>
                            <option value="Sign Off Document">Sign Off Document</option>
                            <option value="Invoice">Invoice</option>
                            <option value="Contract">Contract</option>
                            <option value="Purchase Order">Purchase Order</option>
                            <option value="Other">Other</option>
                          </select>
                          <input 
                            type="file" 
                            onChange={(e) => setAttachments(prev => prev.map(a => a.id === entry.id ? { ...a, file: e.target.files?.[0] || null } : a))} 
                            className="flex-1 w-full text-sm text-muted file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-theme-btn-primary/10 file:text-theme-icon hover:file:bg-theme-btn-primary/20 cursor-pointer"
                          />
                          <AppButton variant="secondary" type="button" onClick={() => setAttachments(prev => prev.filter(a => a.id !== entry.id))} className="p-2 text-red-500 hover:bg-red-500/10 rounded-lg transition-colors">
                            <X className="h-4 w-4" />
                          </AppButton>
                        </div>
                      ))}
                      {attachments.length === 0 && (
                        <div className={`text-sm text-muted italic p-6 text-center border-2 border-dashed rounded-xl border-border`}>
                          No documents staged for upload. Click "Add Document" to begin.
                        </div>
                      )}
                    </div>
                  </div>

                  {existingAttachments.length > 0 && (
                    <div className="space-y-2 pt-4">
                      <label className="text-sm font-bold text-muted uppercase">Existing Attachments</label>
                      <div className="flex flex-col gap-2">
                        {existingAttachments.map((file, idx) => (
                          <div key={idx} className={`flex items-center justify-between p-3 rounded-xl border bg-elevated border-border`}>
                            <div className="flex items-center gap-3 text-sm overflow-hidden">
                              <div className="p-2 bg-theme-btn-primary/10 text-theme-icon rounded shrink-0">
                                <Paperclip className="h-4 w-4" />
                              </div>
                              <span className="truncate" title={file.name}>{formatFileName(file.name)}</span>
                            </div>
                            <div className="flex items-center gap-1">
                              <AppButton type="button" variant="ghost" size="sm" onClick={() => {
                                const url = supabase.storage.from('amc-attachments').getPublicUrl(`${editRecordId}/${file.name}`).data.publicUrl;
                                window.open(url, '_blank');
                              }}>
                                <Download className="h-4 w-4 text-theme-icon" />
                              </AppButton>
                              {hasPermission("AMC_DELETE") && (
                                <AppButton type="button" variant="ghost" size="sm" onClick={() => deleteAttachment(file.name)}>
                                  <Trash2 className="h-4 w-4 text-red-500" />
                                </AppButton>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted uppercase">Additional Notes</label>
                  <textarea value={formNotes} onChange={(e) => setFormNotes(e.target.value)} className={`w-full p-4 rounded-xl text-sm transition-all focus:ring-2 outline-none resize-none h-full min-h-[150px] bg-elevated border-border text-foreground focus:border-theme-btn-primary focus:ring-theme-btn-primary/20 border`} placeholder="Any additional details, terms and conditions, or internal comments..." />
                </div>
              </div>
            </div>

            <div className={`fixed bottom-0 left-0 w-full p-4 border-t shadow-2xl flex items-center justify-end gap-4 z-50 bg-surface/90 border-border backdrop-blur-md`}>
              <div className="w-full max-w-[98%] mx-auto flex justify-end items-center gap-4">
                <div className="flex justify-end gap-4 shrink-0">
                  <AppButton type="button" variant="outline" size="lg" onClick={() => setShowModal(false)} disabled={uploading}>
                    Cancel
                  </AppButton>
                  <AppButton type="submit" variant="primary" size="lg" disabled={uploading} leftIcon={uploading ? <Loader2 className="h-5 w-5 animate-spin" /> : undefined} className="min-w-[200px]">
                    {uploading ? 'Saving Data...' : 'Save Subscription Record'}
                  </AppButton>
                </div>
              </div>
            </div>
            
          </form>
            </div>

            {activeTab === 'Payments' && editRecordId && (
              <div className="p-6 md:p-8">
                <AMCPaymentsTab amcId={editRecordId} isLightMode={isLightMode} />
              </div>
            )}

            {activeTab === 'Transactions' && editRecordId && (
              <div className="p-6 md:p-8">
                <AMCTransactionsTab amcId={editRecordId} isLightMode={isLightMode} onUpdate={fetchRecords} />
              </div>
            )}

            {activeTab === 'Renewals' && editRecordId && (
              <div className="p-6 md:p-8">
                <AMCRenewalsTab 
                  amcId={editRecordId} 
                  isLightMode={isLightMode} 
                  onUpdate={fetchRecords} 
                  currentExpiryDate={formExpiryDate}
                />
              </div>
            )}

            {activeTab === 'Allocations' && editRecordId && (
              <div className="p-6 md:p-8">
                <AMCAllocationsTab amcId={editRecordId} isLightMode={isLightMode} onUpdate={fetchRecords} />
              </div>
            )}

          </div>
        </div>
      )}

      {/* Validation Error Popup */}
      {errorAlert && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-surface/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className={`p-6 rounded-2xl shadow-2xl max-w-sm w-full mx-4 border animate-in zoom-in-95 duration-200 bg-surface border-border`}>
            <div className="flex flex-col items-center text-center space-y-4">
              <div className="h-14 w-14 rounded-full bg-rose-500/10 flex items-center justify-center">
                <AlertTriangle className="h-7 w-7 text-rose-500" />
              </div>
              <div>
                <h3 className="text-lg font-bold text-rose-500">Validation Error</h3>
                <p className={`text-sm mt-2 text-muted`}>{errorAlert}</p>
              </div>
              <AppButton variant="primary" className="w-full mt-4 bg-rose-500 hover:bg-rose-600 border-none text-white" onClick={() => setErrorAlert(null)}>
                Okay, got it
              </AppButton>
            </div>
          </div>
        </div>
      )}
    </PageContainer>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { AppCard, AppCardHeader, AppCardTitle } from "@/components/ui/AppCard";
import { AppBadge } from "@/components/ui/AppBadge";
import { AppButton } from "@/components/ui/AppButton";
import { 
  AppTableContainer, 
  AppTable, 
  AppTableHeader, 
  AppTableBody, 
  AppTableRow, 
  AppTableHead, 
  AppTableCell 
} from "@/components/ui/AppTable";
import { Trash2, AlertOctagon, Archive, ShieldAlert, FolderKanban, Ticket, RefreshCcw, CheckSquare, FileText, Users, Building, UserCog, Building2 } from "lucide-react";
import { 
  fetchComplianceWorkspaces, 
  fetchComplianceTasks, 
  fetchComplianceRequirements,
  fetchComplianceMaster,
  hardDeleteEntity, 
  restoreEntity,
  ComplianceEntity
} from "@/lib/actions/compliance";
import { usePermissions } from "@/hooks/usePermissions";
import { MoveTasksModal } from "@/components/tasks/MoveTasksModal";

type ViewType = "active" | "deleted";

const TABS = [
  { id: 'workspaces', label: 'Workspaces', icon: FolderKanban, entity: 'workspaces', nameKey: 'workspace_name', codeKey: 'workspace_code' },
  { id: 'tasks', label: 'Tasks', icon: Ticket, entity: 'tasks', nameKey: 'subject', codeKey: 'id' },
  { id: 'requirements', label: 'Requirements', icon: FileText, entity: 'requirements', nameKey: 'title', codeKey: 'code' },
  { id: 'user_master', label: 'Users', icon: Users, entity: 'user_master', nameKey: 'full_name', codeKey: 'user_code' },
  { id: 'status_master', label: 'Statuses', icon: CheckSquare, entity: 'status_master', nameKey: 'status_name', codeKey: 'status_code' },
  { id: 'priority_master', label: 'Priorities', icon: AlertOctagon, entity: 'priority_master', nameKey: 'priority_name', codeKey: 'priority_code' },
  { id: 'department_master', label: 'Departments', icon: Building, entity: 'department_master', nameKey: 'department_name', codeKey: 'department_code' },
  { id: 'designation_master', label: 'Designations', icon: UserCog, entity: 'designation_master', nameKey: 'designation_name', codeKey: 'designation_code' },
  { id: 'company_master', label: 'Companies', icon: Building2, entity: 'company_master', nameKey: 'company_name', codeKey: 'company_code' },
];

export default function DataRetentionClient() {
  const { roleCode, hasPermission } = usePermissions();
  const isSuperAdmin = roleCode === "SUPER_ADMIN";
  const canRestore = isSuperAdmin || hasPermission("TRASH_UPDATE");
  const canPurge = isSuperAdmin || hasPermission("TRASH_DELETE");

  const [activeTab, setActiveTab] = useState<string>("workspaces");
  const [activeView, setActiveView] = useState<ViewType>("active");
  const [isLoading, setIsLoading] = useState(false);
  
  const [records, setRecords] = useState<any[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Deletion/Restore State
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [errorBanner, setErrorBanner] = useState<string | null>(null);
  const [successBanner, setSuccessBanner] = useState<string | null>(null);
  
  // Custom Modal for Foreign Key Error
  const [showErrorModal, setShowErrorModal] = useState<boolean>(false);
  const [errorDetails, setErrorDetails] = useState<string>("");

  // Move Tasks Modal State
  const [isMoveModalOpen, setIsMoveModalOpen] = useState(false);

  const currentTabConfig = TABS.find(t => t.id === activeTab) || TABS[0];

  const loadData = async () => {
    setIsLoading(true);
    try {
      const isDeleted = activeView === "deleted";
      let data = [];
      
      if (activeTab === "workspaces") {
        data = await fetchComplianceWorkspaces(isDeleted);
      } else if (activeTab === "tasks") {
        data = await fetchComplianceTasks(isDeleted);
      } else if (activeTab === "requirements") {
        data = await fetchComplianceRequirements(isDeleted);
      } else {
        data = await fetchComplianceMaster(currentTabConfig.entity, currentTabConfig.nameKey, currentTabConfig.codeKey, isDeleted);
      }
      
      setRecords(data);
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
    setSelectedIds(new Set());
    setErrorBanner(null);
    setSuccessBanner(null);
  }, [activeTab, activeView]);

  const toggleSelection = (id: string) => {
    const newSelection = new Set(selectedIds);
    if (newSelection.has(id)) newSelection.delete(id);
    else newSelection.add(id);
    setSelectedIds(newSelection);
  };

  const toggleAll = (ids: string[]) => {
    if (selectedIds.size === ids.length) setSelectedIds(new Set());
    else setSelectedIds(new Set(ids));
  };

  const handleAction = async (actionType: 'restore' | 'purge', ids: string[]) => {
    if (ids.length === 0) return;
    
    if (actionType === 'purge') {
      if (!confirm(`CRITICAL WARNING: You are about to permanently purge ${ids.length} record(s). This action CANNOT be undone. Proceed?`)) {
        return;
      }
    }

    setIsProcessing(true);
    setErrorBanner(null);
    setSuccessBanner(null);
    
    try {
      let result;
      if (actionType === 'restore') {
        result = await restoreEntity(currentTabConfig.entity as ComplianceEntity, ids);
        if (result.success) setSuccessBanner(`Successfully restored ${ids.length} record(s).`);
      } else {
        result = await hardDeleteEntity(currentTabConfig.entity as ComplianceEntity, ids);
        if (result.success) setSuccessBanner(`Successfully purged ${ids.length} record(s).`);
      }
      
      if (!result.success && result.error) {
        if (result.error.includes('attached child records') || result.error.includes('foreign_key_violation')) {
          setErrorDetails(result.error);
          setShowErrorModal(true);
        } else {
          setErrorBanner(result.error);
        }
      } else {
        setSelectedIds(new Set());
        await loadData();
      }
    } catch (e: any) {
      setErrorBanner(e.message || "An unexpected error occurred");
    } finally {
      setIsProcessing(false);
    }
  };

  const renderDataGrid = () => (
    <div className="space-y-4">
      {selectedIds.size > 0 && (
        <div className="bg-surface/5 border border-white/10 rounded-lg p-3 flex items-center justify-between mx-4 mt-4">
          <span className="text-sm font-bold text-muted">{selectedIds.size} record(s) selected</span>
          <div className="flex gap-2">
            {activeView === "deleted" ? (
              <>
                {canRestore && (
                  <AppButton variant="secondary" size="sm" onClick={() => handleAction('restore', Array.from(selectedIds))} disabled={isProcessing} leftIcon={<RefreshCcw className="h-4 w-4" />}>
                    Restore Selected
                  </AppButton>
                )}
                {canPurge && (
                  <AppButton variant="destructive" size="sm" onClick={() => handleAction('purge', Array.from(selectedIds))} disabled={isProcessing} leftIcon={<Trash2 className="h-4 w-4" />}>
                    Purge Selected
                  </AppButton>
                )}
              </>
            ) : (
              <>
                {activeTab === "tasks" && (
                  <AppButton variant="primary" size="sm" onClick={() => setIsMoveModalOpen(true)} disabled={isProcessing}>
                    Move Tasks to Workspace
                  </AppButton>
                )}
              </>
            )}
          </div>
        </div>
      )}
      <AppTableContainer>
        <AppTable>
          <AppTableHeader>
            <tr>
              {(activeView === "deleted" || activeTab === "tasks") && (
                <AppTableHead className="w-[40px]">
                  <input type="checkbox" checked={selectedIds.size === records.length && records.length > 0} onChange={() => toggleAll(records.map(r => r.id))} className="rounded border-border bg-surface/20" />
                </AppTableHead>
              )}
              <AppTableHead>Code / ID</AppTableHead>
              <AppTableHead>Name / Title</AppTableHead>
              <AppTableHead>Last Updated</AppTableHead>
              <AppTableHead className="text-right">Actions</AppTableHead>
            </tr>
          </AppTableHeader>
        <AppTableBody>
          {records.map((record) => (
            <AppTableRow key={record.id}>
              {(activeView === "deleted" || activeTab === "tasks") && (
                <AppTableCell>
                  <input type="checkbox" checked={selectedIds.has(record.id)} onChange={() => toggleSelection(record.id)} className="rounded border-border bg-surface/20" />
                </AppTableCell>
              )}
              <AppTableCell className="font-mono text-xs">{record[currentTabConfig.codeKey] || record.id.split('-')[0]}</AppTableCell>
              <AppTableCell className="font-semibold">{record[currentTabConfig.nameKey] || 'N/A'}</AppTableCell>
              <AppTableCell className="text-xs text-muted">{new Date(record.updated_at).toLocaleString()}</AppTableCell>
              <AppTableCell className="text-right">
                {activeView === "deleted" ? (
                  <div className="flex justify-end gap-2">
                    {canRestore && (
                      <AppButton variant="secondary" size="sm" onClick={() => handleAction('restore', [record.id])} disabled={isProcessing}>
                        Restore
                      </AppButton>
                    )}
                    {canPurge && (
                      <AppButton variant="destructive" size="sm" onClick={() => handleAction('purge', [record.id])} disabled={isProcessing} leftIcon={<Trash2 className="h-3.5 w-3.5" />}>
                        Purge
                      </AppButton>
                    )}
                  </div>
                ) : (
                  <AppBadge variant="success">Active Record</AppBadge>
                )}
              </AppTableCell>
            </AppTableRow>
          ))}
          {records.length === 0 && (
            <AppTableRow>
              <AppTableCell colSpan={(activeView === "deleted" || activeTab === "tasks") ? 5 : 4} className="text-center py-8 text-muted">
                {isLoading ? "Loading records..." : "No records found in this view."}
              </AppTableCell>
            </AppTableRow>
          )}
        </AppTableBody>
      </AppTable>
    </AppTableContainer>
    </div>
  );

  return (
    <div className="space-y-6">
      
      {/* Error Popup Modal */}
      {showErrorModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-surface/60 backdrop-blur-sm">
          <div className="bg-rose-950 border border-rose-500/50 rounded-2xl p-6 max-w-md w-full shadow-2xl shadow-rose-900/20">
            <div className="flex items-center gap-3 text-rose-500 mb-4">
              <ShieldAlert className="h-8 w-8" />
              <h3 className="text-xl font-bold">Deletion Blocked</h3>
            </div>
            <p className="text-rose-200/80 text-sm mb-6 leading-relaxed">
              This record cannot be permanently deleted because active transactions or records are currently attached to it. 
              <br/><br/>
              <strong>System Message:</strong> {errorDetails}
              <br/><br/>
              Please delete or reassign all attached tasks, workspaces, or requirements before purging this master record.
            </p>
            <div className="flex justify-end">
              <AppButton variant="secondary" onClick={() => setShowErrorModal(false)}>
                Acknowledge
              </AppButton>
            </div>
          </div>
        </div>
      )}

      {/* Action Banners */}
      {errorBanner && (
        <div className="p-4 rounded-xl border border-rose-500/30 bg-rose-500/10 flex items-start gap-3">
          <AlertOctagon className="h-5 w-5 text-rose-500 shrink-0 mt-0.5" />
          <div className="space-y-1 text-sm">
            <h4 className="font-bold text-rose-500 uppercase tracking-wider">Action Failed</h4>
            <p className="text-rose-400/80">{errorBanner}</p>
          </div>
        </div>
      )}
      
      {successBanner && (
        <div className="p-4 rounded-xl border border-emerald-500/30 bg-emerald-500/10 flex items-start gap-3">
          <CheckSquare className="h-5 w-5 text-emerald-500 shrink-0 mt-0.5" />
          <div className="space-y-1 text-sm">
            <h4 className="font-bold text-emerald-500 uppercase tracking-wider">Success</h4>
            <p className="text-emerald-400/80">{successBanner}</p>
          </div>
        </div>
      )}

      {/* Module Tabs (Scrollable for many tabs) */}
      <div className="pb-4">
        <div className="flex gap-1.5 overflow-x-auto p-1.5 bg-surface/50 dark:bg-surface/30 border border-border/60 dark:border-white/5 rounded-xl w-max max-w-full shadow-sm scrollbar-thin scrollbar-thumb-white/10 scrollbar-track-transparent">
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 px-5 py-2 text-[13px] font-bold rounded-lg transition-all whitespace-nowrap outline-none flex items-center justify-center min-w-[120px] ${
                  isActive 
                    ? 'bg-surface dark:bg-surface text-theme-icon dark:text-theme-icon shadow-sm border border-border/50 dark:border-white/10' 
                    : 'text-muted hover:text-foreground dark:text-muted dark:hover:text-muted hover:bg-elevated/50 dark:hover:bg-surface/5 border border-transparent'
                }`}
              >
                <Icon className="h-4 w-4" />
                {tab.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* View Toggle (Active vs Deleted) */}
      <AppCard className="overflow-hidden">
        <AppCardHeader className="flex flex-row items-center justify-between pb-4 border-b border-white/5">
          <div className="flex items-center gap-4">
            <AppCardTitle className="flex items-center gap-2 text-foreground">
              <Archive className="h-4 w-4" />
              <span>{currentTabConfig.label} Registry</span>
            </AppCardTitle>
            
            <div className="flex bg-surface/40 rounded-lg p-1 border border-white/10">
              <AppButton variant="secondary"
                onClick={() => setActiveView("active")}
                className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${
                  activeView === "active" ? "bg-surface/20 text-white shadow-sm" : "text-muted hover:text-muted"
                }`}
              >
                Active Records
              </AppButton>
              <AppButton variant="secondary"
                onClick={() => setActiveView("deleted")}
                className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-1.5 ${
                  activeView === "deleted" ? "bg-rose-500/20 text-rose-400 shadow-sm border border-rose-500/30" : "text-muted hover:text-muted"
                }`}
              >
                <ShieldAlert className="h-3.5 w-3.5" />
                Recycle Bin
              </AppButton>
            </div>
          </div>
        </AppCardHeader>

        <div className="p-0">
          {renderDataGrid()}
        </div>
      </AppCard>

      <MoveTasksModal
        open={isMoveModalOpen}
        onOpenChange={setIsMoveModalOpen}
        taskIds={Array.from(selectedIds)}
        tasks={records}
        onSuccess={() => {
          setSelectedIds(new Set());
          loadData();
          setSuccessBanner("Tasks successfully moved to the new workspace.");
        }}
      />
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { createClient } from "@/utils/supabase/client";
import { AppInput } from "@/components/ui/AppInput";
import { AppButton } from "@/components/ui/AppButton";
import { 
  ShieldCheck, 
  Lock, 
  Mail, 
  ArrowRight, 
  AlertCircle, 
  User,
  Zap
} from "lucide-react";

export default function LoginPage() {
  const router = useRouter();
  const supabase = createClient();
  
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  
  const [loading, setLoading] = useState(false);
  const [ssoLoading, setSsoLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  useEffect(() => {
    const checkSession = async () => {
      if (typeof window === "undefined") return;
      
      const searchParams = new URLSearchParams(window.location.search);
      const isLogout = searchParams.get("action") === "logout" || searchParams.get("reason") === "logout";
      const isTimeout = searchParams.get("reason") === "timeout";
      const isTerminated = searchParams.get("reason") === "terminated";
      const isConcurrent = searchParams.get("reason") === "concurrent_login";
      const urlError = searchParams.get("error");
      const urlErrorDesc = searchParams.get("error_description");

      const hashParams = new URLSearchParams(window.location.hash.substring(1));
      const hashError = hashParams.get("error");
      const hashErrorDesc = hashParams.get("error_description");

      const finalError = urlErrorDesc || urlError || hashErrorDesc || hashError;
      if (finalError) {
        setErrorMsg(`Authentication failed: ${finalError.replace(/\+/g, ' ')}`);
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (isLogout) {
        const { data: { session } } = await supabase.auth.getSession();
        if (session) {
          await Promise.race([supabase.auth.signOut(), new Promise(resolve => setTimeout(resolve, 800))]);
        }
        setSuccessMsg("You have been successfully logged out.");
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (isTerminated) {
        const { data: { session } } = await supabase.auth.getSession();
        if (session) {
          await Promise.race([supabase.auth.signOut(), new Promise(resolve => setTimeout(resolve, 800))]);
        }
        setErrorMsg("Your session was terminated by an administrator or remotely.");
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (isConcurrent) {
        const { data: { session } } = await supabase.auth.getSession();
        if (session) {
          await Promise.race([supabase.auth.signOut(), new Promise(resolve => setTimeout(resolve, 800))]);
        }
        setErrorMsg("Your account was logged into on another device.");
        window.history.replaceState({}, document.title, window.location.pathname);
      } else if (isTimeout) {
        const { data: { session } } = await supabase.auth.getSession();
        if (session) {
          await Promise.race([supabase.auth.signOut(), new Promise(resolve => setTimeout(resolve, 800))]);
        }
        setErrorMsg("Your session expired. Please sign in again.");
        window.history.replaceState({}, document.title, window.location.pathname);
      } else {
        const { data: { session } } = await supabase.auth.getSession();
        if (session) {
          router.push("/");
        }
      }
    };

    checkSession();
  }, [router, supabase.auth]);

  const handleStandardAuthSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);
    setSuccessMsg(null);

    if (!email.trim() || !password) {
      setErrorMsg("Please fill in all required fields.");
      return;
    }

    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: email.trim(),
        password: password,
      });

      if (error) throw error;

      if (data.user) {
        try {
          const currentToken = typeof window !== "undefined" ? localStorage.getItem("app_session_token") : null;
          const { data: sessionData } = await supabase
            .from("active_sessions")
            .select("session_token, last_active_at")
            .eq("user_id", data.user.id)
            .maybeSingle();

          if (sessionData && sessionData.last_active_at) {
            const lastActive = new Date(sessionData.last_active_at).getTime();
            const now = Date.now();
            const isRecent = (now - lastActive) < 5 * 60 * 1000;
            const isDifferentSession = currentToken ? sessionData.session_token !== currentToken : true;

            if (isRecent && isDifferentSession) {
              const proceed = window.confirm("Your account is currently active on another device or browser. Continuing will terminate your other session. Do you want to continue?");
              if (!proceed) {
                await Promise.race([supabase.auth.signOut(), new Promise(resolve => setTimeout(resolve, 800))]);
                setLoading(false);
                return;
              }
            }
          }
        } catch (e) {}
      }

      window.location.href = "/";

    } catch (err: any) {
      setErrorMsg(err.message || "An error occurred during authentication.");
    } finally {
      setLoading(false); 
    }
  };

  const handleMicrosoftLogin = async () => {
    try {
      setErrorMsg(null);
      setSsoLoading(true);
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'azure',
        options: {
          scopes: 'email profile User.Read',
          redirectTo: `${window.location.origin}/auth/callback`,
          queryParams: {
            prompt: 'consent'
          }
        }
      });
      if (error) throw error;
    } catch (err: any) {
      setErrorMsg(err.message || "Failed to initialize Microsoft login.");
      setSsoLoading(false);
    }
  };

  return (
    <div className="dark theme-dark flex h-screen w-full bg-[#0A0D14] text-white font-sans overflow-hidden" data-theme="glass-intelligence" style={{ colorScheme: 'dark' }}>
      <style dangerouslySetInnerHTML={{__html: `
        input:-webkit-autofill,
        input:-webkit-autofill:hover, 
        input:-webkit-autofill:focus, 
        input:-webkit-autofill:active {
            -webkit-box-shadow: 0 0 0 30px #0A0D14 inset !important;
            -webkit-text-fill-color: white !important;
        }
      `}} />
      {/* LEFT PANEL - Branding / Image Split */}
      <div className="relative hidden lg:flex flex-col w-1/2 h-full overflow-hidden bg-slate-950">
        <Image 
          src="/login-bg.png"
          alt="Abstract Background"
          fill
          priority
          className="object-cover opacity-90"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-slate-900/70 to-slate-900/40"></div>
        
        {/* Abstract Glow Effects */}
        <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] rounded-full bg-theme-btn-primary/30 blur-[120px] animate-pulse duration-[10000ms]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[60%] h-[60%] rounded-full bg-blue-500/20 blur-[150px] animate-pulse duration-[12000ms]"></div>

        <div className="relative z-10 flex flex-col items-center justify-center h-full p-12 lg:p-16 text-center">
          
          {/* Logo - Pushed to Absolute Top */}
          <div className="absolute top-12 lg:top-16 left-0 right-0 flex flex-col items-center gap-5 animate-in fade-in slide-in-from-top-8 duration-1000 delay-300">
            <div className="relative h-24 w-64 lg:h-32 lg:w-80 bg-white rounded-2xl p-4 shadow-2xl border border-white/30 flex items-center justify-center">
              <img 
                src="/Chandak-Group-Final-Logo.svg" 
                alt="Chandak Logo" 
                className="h-full w-auto max-w-full object-contain p-2"
              />
            </div>
          </div>

          {/* Main Text - Perfectly Centered */}
          <div className="max-w-xl mt-24 animate-in fade-in slide-in-from-bottom-8 duration-1000 delay-500">
            <h1 className="text-4xl lg:text-5xl font-bold tracking-tight !text-white mb-12 leading-tight drop-shadow-lg">
              Intelligent Governance <br />
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-cyan-400">
                & Enterprise Mastery
              </span>
            </h1>
            <p className="!text-slate-200 text-lg font-medium leading-relaxed max-w-md mx-auto drop-shadow-md">
              Securely orchestrate enterprise operations, manage identities, and automate workflows in one unified platform.
            </p>
          </div>

        </div>
      </div>

      {/* RIGHT PANEL - Authentication Form */}
      <div className="w-full lg:w-1/2 h-full flex flex-col overflow-y-auto bg-[#0F131E] lg:bg-[#0A0D14] relative text-white">
        {/* Subtle grid on right panel for texture */}
        <div className="absolute inset-0 bg-[linear-gradient(to_right,var(--border)_1px,transparent_1px),linear-gradient(to_bottom,var(--border)_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_0%,#000_70%,transparent_100%)] opacity-20 pointer-events-none"></div>

        <div className="flex-1 flex items-center justify-center p-6 lg:p-12 xl:p-24 relative z-10 min-h-full">
          <div className="w-full max-w-md animate-in fade-in zoom-in-95 duration-700 fill-mode-both">
            
            <div className="lg:hidden flex flex-col items-center justify-center mb-10">
              <div className="relative h-20 w-56 flex items-center justify-center bg-white rounded-xl p-3 shadow-lg border border-white/20">
                <img 
                  src="/Chandak-Group-Final-Logo.svg" 
                  alt="Chandak Logo" 
                  className="h-full w-auto max-w-full object-contain"
                />
              </div>
            </div>

            <div className="mb-10 lg:mb-12">
              <h2 className="text-3xl font-bold mb-2" style={{ color: '#ffffff' }}>
                Welcome back
              </h2>
              <p className="mb-4" style={{ color: '#9ca3af' }}>
                Please enter your details to sign in to your workspace.
              </p>
            </div>

            {/* Realtime Alert Displays */}
            {errorMsg && (
              <div className="mb-6 p-4 rounded-xl bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-900/50 text-red-600 dark:text-red-400 text-sm flex items-start gap-3 animate-in fade-in slide-in-from-top-2 duration-300">
                <AlertCircle className="h-5 w-5 shrink-0 mt-0.5" />
                <div className="space-y-1">
                  <strong className="font-semibold block">Authentication Failed</strong>
                  <span className="opacity-90">{errorMsg}</span>
                </div>
              </div>
            )}

            {successMsg && (
              <div className="mb-6 p-4 rounded-xl bg-emerald-50 dark:bg-emerald-950/30 border border-emerald-200 dark:border-emerald-900/50 text-emerald-600 dark:text-emerald-400 text-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2 duration-300">
                <ShieldCheck className="h-5 w-5 shrink-0" />
                <span className="font-medium">{successMsg}</span>
              </div>
            )}

            {/* Form */}
            <form onSubmit={handleStandardAuthSubmit} className="space-y-5" autoComplete="off">

              <div className="space-y-2">
                <label className="text-sm font-bold uppercase tracking-wider" style={{ color: '#9ca3af' }}>
                  Email Address
                </label>
                <AppInput 
                  name="email"
                  type="email"
                  placeholder="user@enterprise.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  leftIcon={<Mail className="h-4 w-4 text-muted-foreground" />}
                  className="h-12 bg-[#0A0D14] lg:bg-surface/5 border-white/10 focus:bg-[#0A0D14] transition-colors text-white"
                  required
                />
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-bold uppercase tracking-wider" style={{ color: '#9ca3af' }}>
                    Password
                  </label>
                  <Link href="#" onClick={(e) => { e.preventDefault(); alert("Contact administrator to reset password."); }} className="text-xs font-semibold text-theme-icon hover:text-theme-icon/80 transition-colors">
                    Forgot password?
                  </Link>
                </div>
                <AppInput 
                  name="password"
                  type="password"
                  placeholder="••••••••••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  leftIcon={<Lock className="h-4 w-4 text-muted-foreground" />}
                  className="h-12 bg-[#0A0D14] lg:bg-surface/5 border-white/10 focus:bg-[#0A0D14] transition-colors text-white"
                  required
                />
              </div>

              <AppButton 
                type="submit" 
                variant="primary"
                disabled={loading || !!successMsg}
                className="w-full h-12 mt-4 text-base font-semibold shadow-lg shadow-theme-btn-primary/20 hover:shadow-theme-btn-primary/40 hover:-translate-y-0.5 active:translate-y-0 transition-all duration-200"
              >
                {loading ? (
                  <div className="flex items-center gap-2">
                    <span className="h-5 w-5 rounded-full border-2 border-white/20 border-t-white animate-spin" />
                    <span>Processing...</span>
                  </div>
                ) : (
                  <div className="flex items-center justify-center gap-2 w-full">
                    <span>Sign In</span>
                    <ArrowRight className="h-4 w-4" />
                  </div>
                )}
              </AppButton>
            </form>

            {/* Navigate to Registration */}
            <div className="mt-8 text-center">
              <span className="text-sm font-medium text-muted-foreground">
                Don't have an account? <Link href="/register" className="text-theme-icon font-semibold hover:underline transition-colors">Register now</Link>
              </span>
            </div>

            <div className="relative py-8">
              <div className="absolute inset-0 flex items-center">
                <span className="w-full border-t border-border"></span>
              </div>
              <div className="relative flex justify-center text-xs uppercase">
                <span className="bg-[#0F131E] lg:bg-[#0A0D14] px-4 font-semibold tracking-widest backdrop-blur-sm" style={{ color: '#9ca3af' }}>
                  Or Continue With
                </span>
              </div>
            </div>

            <AppButton
              type="button"
              variant="outline"
              onClick={handleMicrosoftLogin}
              disabled={ssoLoading}
              className="w-full h-12 flex items-center justify-center gap-3 transition-all duration-200 hover:bg-surface/5 font-semibold bg-[#0A0D14] lg:bg-transparent border border-white/10"
            >
              {ssoLoading ? (
                <div className="flex items-center gap-2 text-white">
                  <span className="h-5 w-5 rounded-full border-2 border-current border-t-transparent animate-spin" />
                  Connecting to Microsoft...
                </div>
              ) : (
                <div className="flex items-center gap-2 text-white">
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 21 21">
                    <path fill="#f25022" d="M1 1h9v9H1z"/>
                    <path fill="#00a4ef" d="M1 11h9v9H1z"/>
                    <path fill="#7fba00" d="M11 1h9v9h-9z"/>
                    <path fill="#ffb900" d="M11 11h9v9h-9z"/>
                  </svg>
                  Continue with Microsoft
                </div>
              )}
            </AppButton>

          </div>
        </div>
      </div>

    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { createClient } from "@/utils/supabase/client";
import { AppCard, AppCardHeader, AppCardTitle, AppCardContent } from "@/components/ui/AppCard";
import { AppButton } from "@/components/ui/AppButton";
import { AppInput } from "@/components/ui/AppInput";
import { useTheme } from "@/components/theme/ThemeProvider";
import { 
  UserPlus, 
  Lock, 
  Mail, 
  User, 
  ArrowRight, 
  AlertCircle, 
  CheckCircle2, 
  Building2, 
  ShieldCheck,
  Briefcase,
  Camera
} from "lucide-react";

const PRESET_AVATARS = [
  "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=200"
];

export default function RegisterPage() {
  const router = useRouter();
  const supabase = createClient();
  const { theme } = useTheme();
  const isLight = ["executive-light", "material-ocean", "aurora-breeze", "pure-elegance", "pristine-white"].includes(theme);
  
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [department, setDepartment] = useState("");
  const [designation, setDesignation] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [photo, setPhoto] = useState(PRESET_AVATARS[0]);
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [departments, setDepartments] = useState<any[]>([]);
  const [designations, setDesignations] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  // Fetch master data for registration
  useEffect(() => {
    async function loadData() {
      const [deptRes, desigRes] = await Promise.all([
        supabase.from("departments").select("id, name").eq("is_deleted", false),
        supabase.from("designations").select("id, name, department_id")
      ]);
      if (deptRes.data) setDepartments(deptRes.data);
      if (desigRes.data) setDesignations(desigRes.data);
    }
    loadData();
  }, []);

  const filteredDesignations = designations.filter(d => d.department_id === department);

  const handleRegistrationSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);
    setSuccessMsg(null);

    if (!fullName.trim() || !email.trim() || !password) {
      setErrorMsg("Please fill in all mandatory fields.");
      return;
    }

    if (!email.trim().toLowerCase().endsWith('@chandakgroup.com')) {
      setErrorMsg("Registration is restricted to official @chandakgroup.com email addresses only.");
      return;
    }

    if (password !== confirmPassword) {
      setErrorMsg("Passwords do not match. Please try again.");
      return;
    }

    if (password.length < 8) {
      setErrorMsg("Password must contain at least 8 characters.");
      return;
    }

    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signUp({
        email: email.trim(),
        password: password,
        options: {
          data: {
            full_name: fullName.trim(),
            department_id: department,
            designation_id: designation,
            profile_photo: photo,
            provisioned_roles: ["ROLE_STAFF"]
          }
        }
      });

      if (error) {
        throw error;
      }

      if (data.user && uploadFile) {
        setSuccessMsg("Provisioning identity... Uploading profile imagery...");
        const fileExt = uploadFile.name.split('.').pop();
        const fileName = `${data.user.id}/avatar-${Date.now()}.${fileExt}`;
        
        const { error: uploadError } = await supabase.storage
          .from('profiles')
          .upload(fileName, uploadFile);

        if (!uploadError) {
          const { data: { publicUrl } } = supabase.storage
            .from('profiles')
            .getPublicUrl(fileName);
          
          // Update user_master with the uploaded photo URL
          await supabase
            .from('user_master')
            .update({ profile_photo: publicUrl })
            .eq('id', data.user.id);
        }
      }

      setSuccessMsg("Account successfully registered. Redirecting to Login...");
      setTimeout(() => {
        router.push("/login");
      }, 1500);

    } catch (err: any) {
      setErrorMsg(err.message || "Failed to create user account.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="dark theme-dark flex h-screen w-full bg-[#0A0D14] text-white font-sans overflow-hidden" data-theme="glass-intelligence">
      
      {/* LEFT PANEL - Branding / Image Split */}
      <div className="relative hidden lg:flex flex-col w-1/2 h-full overflow-hidden bg-slate-950">
        <Image 
          src="/login-bg.png"
          alt="Abstract Background"
          fill
          priority
          className="object-cover opacity-90"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-slate-900/70 to-slate-900/40"></div>
        
        {/* Abstract Glow Effects */}
        <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] rounded-full bg-theme-btn-primary/30 blur-[120px] animate-pulse duration-[10000ms]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[60%] h-[60%] rounded-full bg-blue-500/20 blur-[150px] animate-pulse duration-[12000ms]"></div>

        <div className="relative z-10 flex flex-col items-center justify-center h-full p-12 lg:p-16 text-center">
          
          {/* Logo - Pushed to Absolute Top */}
          <div className="absolute top-12 lg:top-16 left-0 right-0 flex flex-col items-center gap-5 animate-in fade-in slide-in-from-top-8 duration-1000 delay-300">
            <div className="relative h-24 w-64 lg:h-32 lg:w-80 bg-white rounded-2xl p-4 shadow-2xl border border-white/30 flex items-center justify-center">
              <img 
                src="/Chandak-Group-Final-Logo.svg" 
                alt="Chandak Logo" 
                className="h-full w-auto max-w-full object-contain p-2"
              />
            </div>
          </div>

          {/* Main Text - Perfectly Centered */}
          <div className="max-w-xl mt-24 animate-in fade-in slide-in-from-bottom-8 duration-1000 delay-500">
            <h1 className="text-4xl lg:text-5xl font-bold tracking-tight !text-white mb-12 leading-tight drop-shadow-lg">
              Intelligent Governance <br />
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-cyan-400">
                & Enterprise Mastery
              </span>
            </h1>
            <p className="!text-slate-200 text-lg font-medium leading-relaxed max-w-md mx-auto drop-shadow-md">
              Securely orchestrate enterprise operations, manage identities, and automate workflows in one unified platform.
            </p>
          </div>

        </div>
      </div>

      {/* RIGHT PANEL - Authentication Form */}
      <div className="w-full lg:w-1/2 h-full flex flex-col overflow-y-auto bg-[#0F131E] lg:bg-[#0A0D14] relative text-white">
        {/* Subtle grid on right panel for texture */}
        <div className="absolute inset-0 bg-[linear-gradient(to_right,var(--border)_1px,transparent_1px),linear-gradient(to_bottom,var(--border)_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_0%,#000_70%,transparent_100%)] opacity-20 pointer-events-none"></div>

        <div className="flex-1 flex items-center justify-center p-6 lg:p-12 xl:p-16 relative z-10 min-h-full">
          <div className="w-full max-w-xl animate-in fade-in zoom-in-95 duration-700 fill-mode-both">
            
            <div className="lg:hidden flex flex-col items-center justify-center mb-8">
              <div className="relative h-20 w-56 flex items-center justify-center bg-white rounded-xl p-3 shadow-lg border border-white/20">
                <img 
                  src="/Chandak-Group-Final-Logo.svg" 
                  alt="Chandak Logo" 
                  className="h-full w-auto max-w-full object-contain"
                />
              </div>
            </div>

            <div className="mb-8 lg:mb-10 text-center">
              <h2 className="text-3xl font-bold text-white mb-2">
                Create an Account
              </h2>
              <p className="text-muted mb-4">
                Register new personnel records to enable authenticated platform access.
              </p>
              
              <div className="p-3 bg-blue-950/30 text-blue-400 rounded-lg text-xs flex items-start text-left gap-2 border border-blue-900/50">
                <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
                <span>
                  <strong>Important:</strong> You must use your official <b>@chandakgroup.com</b> mail ID credentials for access.
                </span>
              </div>
            </div>

            {/* Realtime Alert Displays */}
            {errorMsg && (
              <div className="mb-6 p-4 rounded-xl bg-red-950/30 border border-red-900/50 text-red-400 text-sm flex items-start gap-3 animate-in fade-in duration-300">
                <AlertCircle className="h-5 w-5 shrink-0 mt-0.5" />
                <div className="space-y-1">
                  <strong className="font-semibold block">Error</strong>
                  <span className="opacity-90">{errorMsg}</span>
                </div>
              </div>
            )}

            {successMsg && (
              <div className="mb-6 p-4 rounded-xl bg-emerald-950/30 border border-emerald-900/50 text-emerald-400 text-sm flex items-center gap-3 animate-in fade-in duration-300">
                <CheckCircle2 className="h-5 w-5 shrink-0" />
                <span className="font-medium">{successMsg}</span>
              </div>
            )}

            {/* Registration Submission Inputs */}
            <form onSubmit={handleRegistrationSubmit} className="space-y-6" autoComplete="off">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted block uppercase tracking-wider">
                    Full Name
                  </label>
                  <AppInput 
                    type="text"
                    placeholder="e.g. Richard Hendricks"
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    leftIcon={<User className="h-4 w-4" />}
                    className="h-12 bg-[#0A0D14] lg:bg-surface/5 border-white/10 focus:bg-[#0A0D14] transition-colors text-white"
                    required
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted block uppercase tracking-wider">
                    Email Address
                  </label>
                  <AppInput 
                    type="email"
                    placeholder="e.g. richard@chandakgroup.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    leftIcon={<Mail className="h-4 w-4" />}
                    className="h-12 bg-[#0A0D14] lg:bg-surface/5 border-white/10 focus:bg-[#0A0D14] transition-colors text-white"
                    required
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted block uppercase tracking-wider">
                    Department
                  </label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted pointer-events-none">
                      <Building2 className="h-4 w-4" />
                    </span>
                    <select
                      value={department}
                      onChange={(e) => { setDepartment(e.target.value); setDesignation(""); }}
                      className="w-full h-12 pl-10 pr-3 rounded-xl border text-sm focus:outline-none cursor-pointer transition-colors bg-[#0A0D14] lg:bg-surface/5 border-white/10 focus:bg-[#0A0D14] text-white"
                      required
                    >
                      <option value="" disabled>Select Department</option>
                      {departments.map(dept => (
                        <option key={dept.id} value={dept.id} className="bg-[#0A0D14] text-white">
                          {dept.name}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted block uppercase tracking-wider">
                    Designation
                  </label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted pointer-events-none">
                      <Briefcase className="h-4 w-4" />
                    </span>
                    <select
                      value={designation}
                      onChange={(e) => setDesignation(e.target.value)}
                      disabled={!department}
                      className={`w-full h-12 pl-10 pr-3 rounded-xl border text-sm focus:outline-none cursor-pointer transition-colors bg-[#0A0D14] lg:bg-surface/5 border-white/10 focus:bg-[#0A0D14] text-white ${!department ? "opacity-50 cursor-not-allowed" : ""}`}
                      required
                    >
                      <option value="" disabled>Select Designation</option>
                      {filteredDesignations.map(desig => (
                        <option key={desig.id} value={desig.id} className="bg-[#0A0D14] text-white">
                          {desig.name}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-sm font-bold text-muted block uppercase tracking-wider">
                  Identity Visual (Photo Upload)
                </label>
                <div className="flex flex-col sm:flex-row sm:items-center gap-6 p-5 rounded-xl border border-dashed border-white/20 bg-surface/[0.02]">
                  <div className="h-16 w-16 rounded-xl bg-theme-btn-primary/10 border border-theme-btn-primary/20 flex items-center justify-center overflow-hidden shrink-0">
                    {uploadFile ? (
                      <img src={URL.createObjectURL(uploadFile)} className="h-full w-full object-cover" />
                    ) : (
                      <Camera className="h-5 w-5 text-theme-icon" />
                    )}
                  </div>
                  <div className="flex-1 space-y-2">
                    <p className="text-xs text-muted">Upload a professional portrait or choose a preset below.</p>
                    <input 
                      type="file" 
                      accept="image/*"
                      onChange={(e) => setUploadFile(e.target.files?.[0] || null)}
                      className="hidden" 
                      id="photo-upload"
                    />
                    <label 
                      htmlFor="photo-upload"
                      className="inline-block px-4 py-2 rounded-lg bg-theme-btn-primary/20 text-theme-icon border border-theme-btn-primary/30 text-sm font-bold cursor-pointer hover:bg-theme-btn-primary/40 transition-colors"
                    >
                      Select Image
                    </label>
                  </div>
                </div>

                <div className="flex items-center justify-center gap-4 overflow-x-auto pb-1 custom-scrollbar">
                  {PRESET_AVATARS.map((url, idx) => (
                    <div 
                      key={idx}
                      onClick={() => { setPhoto(url); setUploadFile(null); }}
                      className={`relative shrink-0 h-10 w-10 rounded-full cursor-pointer transition-all border-2 ${
                        photo === url && !uploadFile ? "border-theme-btn-primary scale-110 shadow-lg shadow-purple-500/20" : "border-transparent opacity-50 hover:opacity-100"
                      }`}
                    >
                      <img src={url} alt={`Avatar ${idx}`} className="h-full w-full rounded-full object-cover" />
                      {photo === url && !uploadFile && (
                        <div className="absolute -right-1 -top-1 bg-theme-btn-primary rounded-full p-0.5 shadow-sm">
                          <CheckCircle2 className="h-2 w-2 text-white" />
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 pt-2">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted block uppercase tracking-wider">
                    Password
                  </label>
                  <AppInput 
                    type="password"
                    placeholder="Min 8 characters"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    leftIcon={<Lock className="h-4 w-4" />}
                    className="h-12 bg-[#0A0D14] lg:bg-surface/5 border-white/10 focus:bg-[#0A0D14] transition-colors text-white"
                    required
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-bold text-muted block uppercase tracking-wider">
                    Confirm Password
                  </label>
                  <AppInput 
                    type="password"
                    placeholder="Repeat password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    leftIcon={<Lock className="h-4 w-4" />}
                    className="h-12 bg-[#0A0D14] lg:bg-surface/5 border-white/10 focus:bg-[#0A0D14] transition-colors text-white"
                    required
                  />
                </div>
              </div>

              <div className="pt-6">
                <AppButton 
                  variant="primary" 
                  size="md" 
                  type="submit" 
                  disabled={loading || !!successMsg}
                  className="w-full h-12 font-bold text-base tracking-wide bg-gradient-to-r from-purple-600 to-cyan-600 hover:from-purple-500 hover:to-cyan-500 shadow-lg shadow-purple-500/20 text-white border-none"
                >
                  {loading ? (
                    <span className="flex items-center justify-center gap-2">
                      <span className="h-4 w-4 rounded-full border-2 border-white border-t-transparent animate-spin" />
                      <span>Registering User Account...</span>
                    </span>
                  ) : (
                    <span className="flex items-center justify-center gap-2">
                      <span>Register Account</span>
                      <ArrowRight className="h-4 w-4" />
                    </span>
                  )}
                </AppButton>
              </div>
            </form>

            {/* Back navigation context */}
            <div className="mt-8 text-center">
              <span className="text-sm font-medium text-muted">
                Already have an account? <Link href="/login" className="text-theme-icon font-semibold hover:underline transition-colors">Sign In</Link>
              </span>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { AppCard, AppCardHeader, AppCardTitle, AppCardContent } from "@/components/ui/AppCard";
import { AppTable, AppTableHeader, AppTableRow, AppTableHead, AppTableBody, AppTableCell } from "@/components/ui/AppTable";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { AppButton } from "@/components/ui/AppButton";
import { AppInput } from "@/components/ui/AppInput";
import { AppBadge } from "@/components/ui/AppBadge";
import { Plus, RefreshCw, ArrowLeft, ShieldAlert, Trash2, Paperclip, Eye, Download, CheckCircle, PauseCircle, XCircle, FilePlus, Save, Edit2, AlertTriangle, Briefcase, Server, Calendar, Shield, Clock, FileText, Target, Hourglass, ChevronDown, ChevronRight } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { createClient } from "@/utils/supabase/client";
