                <div className="space-y-1.5">
                  <label className="text-sm font-bold text-muted uppercase tracking-wider">Target End Date</label>
                  <AppInput type="date" min={newWS.start_date || new Date().toISOString().split('T')[0]} value={newWS.end_date} onChange={e => setNewWS({...newWS, end_date: e.target.value})} className={"bg-surface"} />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-sm font-bold text-muted uppercase tracking-wider">Objective Description</label>
                <textarea 
                  className={`w-full h-24 p-3 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-theme-icon transition-colors resize-none ${ "theme-card-structural text-foreground" }`}
                  placeholder="Detailed project requirements, goals, and constraints..."
                  value={newWS.description}
                  onChange={e => setNewWS({...newWS, description: e.target.value})}
                />
              </div>
            </div>

            {/* Section 3: Access & Security */}
            <div className={`p-5 rounded-2xl ${"theme-card-structural shadow-[var(--shadow-ambient)]"}`}>
              <div className="flex items-center gap-2 mb-4">
                <div className={`p-1.5 rounded-lg bg-emerald-100 text-emerald-600`}>
                  <ShieldCheck className="h-4 w-4" />
                </div>
                <h3 className={`text-sm font-bold tracking-wide ${"text-foreground"}`}>Access & Stakeholders</h3>
              </div>

              <div className="space-y-1.5 relative mb-6">
                <div className="flex items-center justify-between border-b border-border dark:border-white/10 pb-1.5 mb-2">
                  <label className="text-[10px] font-bold text-theme-icon uppercase tracking-wider block">Workspace Assignees (Users)</label>
                  <AppButton variant="secondary" 
                    type="button" 
                    onClick={(e) => {
                      e.stopPropagation();
                      const allIds = availableUsers.map(u => u.id);
                      if (newWS.assigneeIds.length === allIds.length && allIds.length > 0) {
                        setNewWS({...newWS, assigneeIds: []});
                      } else {
                        setNewWS({...newWS, assigneeIds: allIds});
                      }
                    }}
                    className={`text-[9px] font-bold uppercase tracking-wider text-theme-icon hover:text-theme-icon`}
                  >
                    {newWS.assigneeIds.length === availableUsers.length && availableUsers.length > 0 ? "Deselect All" : "Select All"}
                  </AppButton>
                </div>

                <div className="relative mb-2 shrink-0">
                  <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted" />
                  <input 
                    type="text" 
                    placeholder="Search personnel..." 
                    value={assigneeSearch} 
                    onChange={e => setAssigneeSearch(e.target.value)} 
                    onClick={e => e.stopPropagation()}
                    onKeyDown={e => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                      }
                    }}
                    className={`w-full pl-8 pr-3 py-2 text-xs rounded-lg focus:outline-none focus:ring-1 focus:ring-theme-icon ${ "theme-card-structural text-foreground" }`}
                  />
                </div>

                <div className={`max-h-[160px] overflow-y-auto space-y-1 pr-1 rounded-xl p-2 border bg-elevated border-border scrollbar-thin scrollbar-thumb-indigo-500/30 scrollbar-track-transparent`}>
                  {availableUsers.filter(u => u.full_name?.toLowerCase().includes(assigneeSearch.toLowerCase()) || u.user_code?.toLowerCase().includes(assigneeSearch.toLowerCase())).map(u => (
                    <label key={u.id} className={`flex items-center gap-3 text-sm p-2 rounded-lg cursor-pointer transition-colors ${
                      "hover:bg-theme-btn-primary/10/50"
                    }`}>
                      <input 
                        type="checkbox" 
                        checked={newWS.assigneeIds.includes(u.id)} 
                        onChange={e => {
                          if (e.target.checked) setNewWS({...newWS, assigneeIds: [...newWS.assigneeIds, u.id]});
                          else setNewWS({...newWS, assigneeIds: newWS.assigneeIds.filter((id: string) => id !== u.id)});
                        }} 
                        className="rounded border-border text-theme-icon focus:ring-theme-icon h-4 w-4" 
                      />
                      <div className="flex flex-col">
                        <span className={"text-foreground font-medium"}>{u.full_name}</span>
                        <span className="opacity-50 text-[10px]">{u.user_code}</span>
                      </div>
                    </label>
                  ))}
                  {availableUsers.length === 0 && <p className="text-xs text-muted p-3 text-center">No users available.</p>}
                </div>
              </div>

              <div className={`p-4 rounded-xl border flex items-center gap-3 transition-colors ${
                newWS.is_public 
                  ? ("bg-theme-btn-primary/10/50 border-theme-icon/30") 
                  : ("bg-elevated border-border")
              }`}>
                <input 
                  type="checkbox" 
                  id="is_public" 
                  checked={newWS.is_public} 
                  onChange={e => {
                    const checked = e.target.checked;
                    if (checked) {
                      const allUserIds = availableUsers.map(u => u.id);
                      setNewWS({...newWS, is_public: true, assigneeIds: allUserIds});
                    } else {
                      setNewWS({...newWS, is_public: false});
                    }
                  }} 
                  className="rounded border-border text-theme-icon focus:ring-theme-icon h-5 w-5 cursor-pointer"
                />
                <label htmlFor="is_public" className="cursor-pointer flex flex-col">
                  <span className={`text-sm font-bold ${"text-foreground"}`}>Public Visibility</span>
                  <span className="text-xs text-muted">Allow any authenticated personnel to view and join this workspace.</span>
                </label>
              </div>
            </div>

          </div>
        </EnterpriseWizardShell>
      )}

      {isCreatingTask && (activeWorkspace || workspaces.length > 0) && (
        <TaskCreationWizard 
          workspaceId={creatingTaskWorkspaceId || activeWorkspace?.id || workspaces[0]?.id} 
          initialParentTaskId={creatingTaskParentId || undefined}
          initialTaskName={creatingTaskInitialName}
          onClose={() => {
            setIsCreatingTask(false);
            setCreatingTaskWorkspaceId(null);
            setCreatingTaskParentId(null);
            setCreatingTaskInitialName("");
          }}
          onSuccess={async (newTask: any) => {
            const wsId = creatingTaskWorkspaceId || activeWorkspace?.id || workspaces[0]?.id;
            await handleTaskWizardSuccess({ ...newTask, workspace_id: wsId });
            setCreatingTaskWorkspaceId(null);
            setCreatingTaskParentId(null);
          }}
        />
      )}

      {/* Toast Notification */}
      {successToast && (
        <div className="fixed bottom-6 right-6 z-[9999] flex items-center gap-2 rounded-xl bg-theme-btn-primary text-white px-4 py-3 shadow-2xl animate-in slide-in-from-bottom-5 duration-300">
          <span className="text-xs font-semibold">{successToast}</span>
        </div>
      )}
      {errorToast && (
        <div className="fixed bottom-6 right-6 z-[9999] flex items-center gap-2 rounded-xl bg-rose-600 text-white px-4 py-3 shadow-2xl animate-in slide-in-from-bottom-5 duration-300">
          <span className="text-xs font-semibold">{errorToast}</span>
        </div>
      )}

      {drawerTask && (
        <TaskDetailDrawer 
          task={drawerTask} 
          onClose={() => setDrawerTask(null)} 
        />
      )}

    </PageContainer>
  );
}

"use client";

import React, { useState, useEffect, useMemo } from "react";
import { 
  X, 
  Download, 
  Printer, 
  RefreshCw, 
  CheckCircle2, 
  Clock, 
  AlertTriangle, 
  Search, 
  Layers, 
  ListTodo, 
  Briefcase, 
  FileText, 
  Building2, 
  TrendingUp, 
  Award, 
  ShieldCheck, 
  ExternalLink,
  Calendar,
  Filter,
  UserCheck
} from "lucide-react";
import { AppCard } from "@/components/ui/AppCard";
import { AppButton } from "@/components/ui/AppButton";
import { AppBadge } from "@/components/ui/AppBadge";
import { AppTable, AppTableHeader, AppTableRow, AppTableHead, AppTableBody, AppTableCell } from "@/components/ui/AppTable";
import { fetchUserPerformanceWorkingSheet, UserPerformanceSummary, UserPerformanceActivity } from "@/lib/actions/userPerformance";
import { formatDistanceToNow, format } from "date-fns";
import { cn } from "@/lib/utils";

interface UserPerformanceWorkingSheetModalProps {
  isOpen: boolean;
  onClose: () => void;
  userNameOrId: string | null;
}

type TabType = "all" | "tasks" | "subtasks" | "tickets" | "requirements" | "workspaces" | "trends";
type TimeRangeType = "all" | "month" | "30days" | "quarter" | "90days";

export function UserPerformanceWorkingSheetModal({
  isOpen,
  onClose,
  userNameOrId
}: UserPerformanceWorkingSheetModalProps) {
  const [data, setData] = useState<UserPerformanceSummary | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<TabType>("all");
  const [timeRange, setTimeRange] = useState<TimeRangeType>("all");
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [priorityFilter, setPriorityFilter] = useState<string>("all");

  useEffect(() => {
    if (isOpen && userNameOrId) {
      loadPerformanceData();
    }
  }, [isOpen, userNameOrId, timeRange]);

  const loadPerformanceData = async () => {
    if (!userNameOrId) return;
    setLoading(true);
    setError(null);
    try {
      const res = await fetchUserPerformanceWorkingSheet(userNameOrId, timeRange);
      if (res.error) {
        setError(res.error);
        setData(null);
      } else {
        setData(res.data);
      }
    } catch (err: any) {
      setError(err.message || "Failed to load performance data");
    } finally {
      setLoading(false);
    }
  };

  // Filter activities based on active tab, search, status, and priority
  const filteredActivities = useMemo(() => {
    if (!data?.activities) return [];

    return data.activities.filter(activity => {
      // Tab filter
      if (activeTab === "tasks" && activity.module !== "Tasks") return false;
      if (activeTab === "subtasks" && activity.module !== "Sub Tasks") return false;
      if (activeTab === "tickets" && activity.module !== "Tickets") return false;
      if (activeTab === "requirements" && activity.module !== "Requirements") return false;
      if (activeTab === "workspaces" && (activity.module !== "Workspaces" && activity.module !== "Sub Workspaces")) return false;

      // Status filter
      if (statusFilter === "resolved" && activity.status !== "Resolved") return false;
      if (statusFilter === "active" && activity.status !== "Active") return false;
      if (statusFilter === "review" && activity.status !== "Review") return false;
      if (statusFilter === "escalated" && activity.status !== "Escalated") return false;
      if (statusFilter === "overdue" && !activity.isOverdue) return false;

      // Priority filter
      if (priorityFilter !== "all" && activity.priority.toLowerCase() !== priorityFilter.toLowerCase()) return false;

      // Keyword search
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const matchTitle = activity.title.toLowerCase().includes(q);
        const matchCode = activity.code?.toLowerCase().includes(q) || false;
        const matchContext = activity.context?.toLowerCase().includes(q) || false;
        const matchRawStatus = activity.rawStatus.toLowerCase().includes(q);
        if (!matchTitle && !matchCode && !matchContext && !matchRawStatus) return false;
      }

      return true;
    });
  }, [data, activeTab, statusFilter, priorityFilter, searchQuery]);

  // Export to CSV
  const handleExportCSV = () => {
    if (!data) return;

    const headers = [
      "Item Code",
      "Module",
      "Title",
      "Context / Workspace",
      "Role",
      "Status",
      "Priority",
      "Created Date",
      "Due Date",
      "Performance Tag"
    ];

    const rows = data.activities.map(a => [
      `"${a.code || a.id}"`,
      `"${a.module}"`,
      `"${(a.title || "").replace(/"/g, '""')}"`,
      `"${(a.context || "").replace(/"/g, '""')}"`,
      `"${a.roleInActivity || "Participant"}"`,
      `"${a.rawStatus}"`,
      `"${a.priority}"`,
      `"${a.createdAt ? format(new Date(a.createdAt), "yyyy-MM-dd HH:mm") : ""}"`,
      `"${a.dueDate ? format(new Date(a.dueDate), "yyyy-MM-dd") : "N/A"}"`,
      `"${a.status === "Resolved" ? (a.isOnTime ? "Completed On-Time" : "Completed Late") : (a.isOverdue ? "Overdue / Breached" : "In Progress")}"`
    ]);

    const summarySection = [
      ["USER PERFORMANCE WORKING SHEET"],
      ["User Name", data.user.fullName],
      ["User Code", data.user.userCode || ""],
      ["Email", data.user.email],
      ["Designation", data.user.designation],
      ["Department", data.user.department],
      ["Period", timeRange.toUpperCase()],
      ["Overall Performance Ratio", `${data.ratios.overallPerformanceRatio}%`],
      ["Rating", data.ratios.performanceRating],
      ["Completion Rate", `${data.ratios.completionRate}%`],
      ["On-Time Delivery Rate", `${data.ratios.onTimeDeliveryRate}%`],
      ["SLA Compliance Rate", `${data.ratios.slaComplianceRate}%`],
      ["Total Work Volume", data.metrics.totalAssigned],
      ["Total Completed", data.metrics.totalCompleted],
      ["Active Workload", data.metrics.totalActive],
      ["Overdue Items", data.metrics.totalOverdue],
      [],
      ["ITEMIZED ACTIVITY WORKING LOG"],
      headers
    ];

    const csvContent = "data:text/csv;charset=utf-8," + 
      summarySection.map(e => e.join(",")).join("\n") + "\n" +
