                                  </AppTableCell>

                                  {/* Target Due */}
                                  <AppTableCell className="text-right text-xs font-mono">
                                    {act.dueDate ? (
                                      <span className={cn(act.isOverdue ? "text-rose-500 font-bold" : "text-muted-foreground")}>
                                        {format(new Date(act.dueDate), "MMM d, yyyy")}
                                      </span>
                                    ) : (
                                      <span className="text-muted-foreground/60">—</span>
                                    )}
                                  </AppTableCell>

                                  {/* Performance Tag */}
                                  <AppTableCell className="text-right">
                                    {isResolved ? (
                                      <span className={cn(
                                        "text-[10px] font-bold px-2 py-0.5 rounded-md",
                                        act.isOnTime 
                                          ? "bg-emerald-500/15 text-emerald-500 border border-emerald-500/30" 
                                          : "bg-amber-500/15 text-amber-500 border border-amber-500/30"
                                      )}>
                                        {act.isOnTime ? "✓ On-Time" : "⚠ Completed Late"}
                                      </span>
                                    ) : act.isOverdue ? (
                                      <span className="text-[10px] font-bold px-2 py-0.5 rounded-md bg-rose-500/15 text-rose-500 border border-rose-500/30">
                                        ✕ Overdue / SLA Risk
                                      </span>
                                    ) : (
                                      <span className="text-[10px] font-medium px-2 py-0.5 rounded-md bg-surface dark:bg-surface/20 text-muted-foreground">
                                        ⏳ In Progress
                                      </span>
                                    )}
                                  </AppTableCell>

                                </AppTableRow>
                              );
                            })
                          )}
                        </AppTableBody>
                      </AppTable>
                    </div>

                    {/* TABLE FOOTER SUMMARY */}
                    <div className="p-3 bg-surface/50 dark:bg-[#0E1320] border-t border-border/60 flex items-center justify-between text-xs text-muted-foreground">
                      <span>Showing <strong>{filteredActivities.length}</strong> of <strong>{data.activities.length}</strong> recorded activities</span>
                      <span className="font-mono text-[11px]">User Performance Working Sheet</span>
                    </div>
                  </div>
                )}

              </div>
            </>
          )}

        </div>

        {/* MODAL FOOTER */}
        <div className="p-4 border-t border-border/60 flex items-center justify-between bg-surface/50 dark:bg-[#0E1320]/80">
          <div className="text-xs text-muted-foreground flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <span>TaskForge Intelligence Governance • Realtime Multi-Module Sync</span>
          </div>
          <AppButton variant="primary" size="sm" onClick={onClose}>
            Done
          </AppButton>
        </div>

      </div>
    </div>
  );
}

"use client";

import React, { useState, useMemo } from "react";
import { Users, ArrowUpRight, FileSpreadsheet } from "lucide-react";
import { AppTable, AppTableHeader, AppTableRow, AppTableHead, AppTableBody, AppTableCell } from "@/components/ui/AppTable";
import { BaseWidget } from "./BaseWidget";
import { UserPerformanceWorkingSheetModal } from "../performance/UserPerformanceWorkingSheetModal";

interface PerformanceWidgetProps {
  metrics?: any[];
}

export function PerformanceWidget({ metrics = [] }: PerformanceWidgetProps) {
  const [selectedUser, setSelectedUser] = useState<string | null>(null);
  const [isSheetOpen, setIsSheetOpen] = useState<boolean>(false);
  
  const teamStats = useMemo(() => {
    const userMap: Record<string, any> = {};
    metrics.forEach(m => {
      if (!m.user || m.user === 'System') return;
      if (!userMap[m.user]) {
        userMap[m.user] = {
          name: m.user,
          initials: m.user.substring(0,2).toUpperCase(),
          closed: 0,
          pts: 0,
          active: 0,
        };
      }
      
      const statusStr = String(m.status).toLowerCase();
      if (statusStr.includes('resolv') || statusStr.includes('done')) {
        userMap[m.user].closed += 1;
        userMap[m.user].pts += 3;
      } else {
        userMap[m.user].active += 1;
      }
    });

    return Object.values(userMap)
      .sort((a, b) => b.closed - a.closed) // Sort by closed items
      .slice(0, 5);
  }, [metrics]);

  const handleOpenUserSheet = (userName: string) => {
    setSelectedUser(userName);
    setIsSheetOpen(true);
  };

  const handleOpenTopPerformer = () => {
    if (teamStats.length > 0) {
      setSelectedUser(teamStats[0].name);
    } else {
      setSelectedUser(null);
    }
    setIsSheetOpen(true);
  };

  const getRole = (i: number) => {
    return "Team Member";
  };

  const getAvgDays = (i: number) => {
    return "2.4d";
  };

  return (
    <>
      <BaseWidget
        id="team-performance"
        title="Team Performance"
        icon={<Users className="w-5 h-5" />}
        className="h-[400px]"
        noPadding
        headerRight={
          <button 
            onClick={handleOpenTopPerformer}
            className="text-xs text-primary hover:text-primary/80 cursor-pointer font-semibold transition-colors flex items-center gap-1 bg-transparent border-0 p-0"
          >
            Full Working Sheet <ArrowUpRight className="w-3 h-3" />
          </button>
        }
      >
        <div className="w-full overflow-auto h-full custom-scrollbar">
          <AppTable className="border-b-0">
            <AppTableHeader className="sticky top-0 z-10 bg-surface/90 dark:bg-[#0B0F19]/90 backdrop-blur-md shadow-sm">
              <AppTableRow className="border-b border-border/50">
                <AppTableHead className="font-semibold text-xs tracking-wider uppercase text-muted-foreground bg-transparent">Member</AppTableHead>
                <AppTableHead className="font-semibold text-xs tracking-wider uppercase text-muted-foreground bg-transparent text-center w-24">Closed</AppTableHead>
                <AppTableHead className="font-semibold text-xs tracking-wider uppercase text-muted-foreground bg-transparent text-center w-24">Story Pts</AppTableHead>
                <AppTableHead className="font-semibold text-xs tracking-wider uppercase text-muted-foreground bg-transparent w-48">Progress</AppTableHead>
                <AppTableHead className="font-semibold text-xs tracking-wider uppercase text-muted-foreground bg-transparent text-right w-24">Avg Progress</AppTableHead>
              </AppTableRow>
            </AppTableHeader>
            <AppTableBody>
              {teamStats.map((u: any, i: number) => {
                const progress = u.closed + u.active > 0 ? Math.round((u.closed / (u.closed + u.active)) * 100) : 0;
                const colors = ['bg-emerald-500/20 text-emerald-500 border-emerald-500/30', 'bg-theme-btn-primary/20 text-theme-icon border-theme-btn-primary/30', 'bg-theme-btn-primary/20 text-theme-icon border-theme-btn-primary/30', 'bg-amber-500/20 text-amber-500 border-amber-500/30', 'bg-rose-500/20 text-rose-500 border-rose-500/30'];
                const fillColors = ['bg-emerald-500', 'bg-theme-btn-primary', 'bg-theme-btn-primary', 'bg-amber-500', 'bg-rose-500'];
                
                const colorCls = colors[i % colors.length];
                const fillCls = fillColors[i % fillColors.length];

                return (
                  <AppTableRow 
                    key={i} 
                    onClick={() => handleOpenUserSheet(u.name)}
                    className="hover:bg-primary/5 dark:hover:bg-primary/10 transition-colors border-b border-border/40 last:border-0 group cursor-pointer"
                    title={`Click to view ${u.name}'s Performance Working Sheet`}
                  >
                    <AppTableCell>
                      <div className="flex items-center gap-3">
                        <div className={`flex items-center justify-center h-8 w-8 rounded-full text-xs font-bold border shadow-sm group-hover:scale-110 transition-transform ${colorCls}`}>
                          {u.initials}
                        </div>
                        <div>
                          <div className="text-sm font-semibold text-foreground group-hover:text-primary transition-colors flex items-center gap-1.5">
                            {u.name}
                            <FileSpreadsheet className="w-3 h-3 opacity-0 group-hover:opacity-80 text-primary transition-opacity" />
                          </div>
                          <div className="text-[10px] text-muted-foreground font-mono uppercase tracking-wider">{getRole(i)}</div>
                        </div>
                      </div>
                    </AppTableCell>
                    <AppTableCell className="text-center font-bold text-lg text-foreground/80 group-hover:text-foreground transition-colors">
                      {u.closed}
                    </AppTableCell>
                    <AppTableCell className="text-center font-bold text-lg text-primary/80 group-hover:text-primary transition-colors">
                      {u.pts}
                    </AppTableCell>
                    <AppTableCell>
                      <div className="flex justify-between text-[10px] font-mono text-muted-foreground mb-1.5 uppercase tracking-wider">
                        <span>Sprint Goal</span><span className="font-bold text-foreground">{progress}%</span>
                      </div>
                      <div className="h-1.5 w-full bg-surface dark:bg-surface/20 rounded-full overflow-hidden">
                        <div className={`h-full ${fillCls} transition-all duration-1000`} style={{ width: `${progress}%` }}></div>
                      </div>
                    </AppTableCell>
                    <AppTableCell className="text-right font-mono text-xs text-muted-foreground font-semibold">
                      {getAvgDays(i)}
                    </AppTableCell>
                  </AppTableRow>
                );
              })}
              {teamStats.length === 0 && (
                <AppTableRow>
                  <AppTableCell colSpan={5} className="text-center py-12 text-muted-foreground border-0">
                    <div className="flex flex-col items-center justify-center">
                      <Users className="w-8 h-8 mb-2 opacity-20" />
                      <span className="text-sm">No team performance data</span>
                    </div>
                  </AppTableCell>
                </AppTableRow>
              )}
            </AppTableBody>
          </AppTable>
        </div>
      </BaseWidget>

      {isSheetOpen && (
        <UserPerformanceWorkingSheetModal
          isOpen={isSheetOpen}
          onClose={() => setIsSheetOpen(false)}
          userNameOrId={selectedUser}
        />
      )}
    </>
  );
}

"use client";

import React, { useState, useEffect, useCallback, useRef } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { createClient } from "@/utils/supabase/client";
import { 
  Search, 
  Bell, 
  PlusCircle, 
  Command, 
  ChevronDown, 
  Layers, 
  ShieldCheck,
  Moon,
  Sun,
  Palette,
  LogOut,
  Clock,
  ShieldAlert,
  User,
  RefreshCw,
  AlertOctagon
} from "lucide-react";
import { useTheme } from "@/components/theme/ThemeProvider";
import RealtimeNotificationsDrawer from "./RealtimeNotificationsDrawer";
import { useProfile } from "@/hooks/usePermissions";
import { AppButton } from "@/components/ui/AppButton";

export default function Navbar() {
  const router = useRouter();
  const supabase = createClient();
  const { theme, setTheme } = useTheme();
  const { data: profileData } = useProfile();
  const userData = profileData || null;

  const [mounted, setMounted] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const isLight = ["light-neumorphic", "pure-white", "pure-white-neumorphic", "amazon-prime-upi"].includes(theme);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setProfileOpen(false);
      }
    }
    if (profileOpen) {
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [profileOpen]);

  const handleExecuteSignOut = async () => {
    setLoggingOut(true);
    setProfileOpen(false);
    try {
      if (userData?.id) {
        // Fire and forget delete so we don't block, but catch any errors
        supabase.from("active_sessions").delete().eq("user_id", userData.id).then(undefined, () => {});
      }
      // Await signout fully to ensure local storage and cookies are cleared
      await supabase.auth.signOut();
    } catch (_) {}
    window.location.href = "/login?action=logout";
  };

  const toggleQuickTheme = () => {
    if (isLight) {
      setTheme("cyberpunk");
    } else {
      setTheme("light-neumorphic");
    }
  };

  return (
    <>
      <header
        className={`bg-surface border-b border-border/60 shadow-[0_4px_24px_-4px_rgba(0,0,0,0.04)] sticky top-0 z-40 flex h-16 w-full shrink-0 font-sans items-center justify-between transition-all duration-300 px-6`}
      >
        <div className="flex items-center gap-4 flex-1 max-w-md">
          <div className="relative flex items-center w-full">
            <Search className="absolute left-3 h-4 w-4 text-muted" />
            <input 
              type="text" 
              placeholder="Search tickets, documentation, quick masters..." 
              className={`h-10 w-full rounded-xl pl-9 pr-12 text-xs focus:outline-none transition-all duration-200 ${ "theme-input-structural text-foreground placeholder-gray-400 focus:theme-card-structural /50 focus:border-theme-btn-primary" }`}
            />
            <div className={`absolute right-2 flex items-center gap-0.5 px-1.5 py-0.5 rounded text-xs font-semibold pointer-events-none ${
              "bg-elevated/60 text-muted"
            }`}>
              <Command className="h-2.5 w-2.5" />
              <span>K</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3 relative">
          <AppButton 
            variant="outline"
            size="icon"
            onClick={toggleQuickTheme}
            className="!h-10 !w-10 rounded-xl theme-card-structural text-muted hover:bg-muted hover:text-foreground"
          >
            {isLight ? <Moon className="h-4 w-4 text-theme-icon" /> : <Sun className="h-4 w-4 text-amber-500" />}
          </AppButton>

          <Link 
            href="/settings"
            className={`relative flex h-10 w-10 items-center justify-center rounded-xl border transition-colors ${
              "bg-elevated border-border text-muted hover:bg-elevated hover:text-foreground"
            }`}
          >
            <Palette className="h-4 w-4 text-theme-icon" />
          </Link>

          <RealtimeNotificationsDrawer />

          <div className="relative" ref={dropdownRef}>
            <div 
              onClick={() => setProfileOpen(!profileOpen)}
              className="flex h-9 w-9 items-center justify-center rounded-full bg-slate-800 text-xs font-medium text-white cursor-pointer border border-transparent hover:border-slate-400 transition-all overflow-hidden"
            >
              {userData?.profile_photo ? (
                <img src={userData.profile_photo} alt="Profile" className="h-full w-full object-cover" />
              ) : (
                userData?.full_name?.split(' ').map((n: string) => n[0]).join('') || 'OP'
              )}
            </div>

            {profileOpen && (
              <>
                <div className={`absolute right-0 top-12 mt-2 w-56 rounded-xl p-1.5 shadow-md z-50 animate-in fade-in zoom-in-95 duration-150 theme-card-structural text-foreground`}>
                  <div className={`px-2 py-2 border-b space-y-0.5 border-border`}>
                    <span className="text-sm font-medium block truncate">{userData?.full_name || 'System Operator'}</span>
                    <span className="text-xs text-muted block truncate">{userData?.email}</span>
                  </div>

                  <div className="py-2 space-y-1">
                    <Link
                      href="/profile"
                      onClick={() => setProfileOpen(false)}
                      className={`w-full text-left px-2 py-2 rounded-lg text-xs transition-colors flex items-center gap-2 font-medium ${
                        "hover:bg-elevated text-muted"
                      }`}
                    >
                      <User className="h-3.5 w-3.5 text-theme-icon" />
                      <span>My Profile & Settings</span>
                    </Link>
                  </div>

                  <div className={`pt-2 border-t border-border`}>
                    <AppButton 
                      variant="destructive"
                      onClick={handleExecuteSignOut}
                      disabled={loggingOut}
                      className="w-full justify-center rounded-lg text-xs font-bold cursor-pointer group mt-2"
                      leftIcon={<LogOut className="h-3.5 w-3.5 group-hover:rotate-12 transition-transform" />}
                    >
                      <span>{loggingOut ? "Terminating Auth..." : "Log Out Securely"}</span>
                    </AppButton>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      </header>


    </>
  );
}

"use client";

import React, { useState, useEffect, Profiler } from "react";
