                        {/* Content Wrapper */}
                        <div className={`flex items-center ${isCompact ? "justify-center w-full h-full" : "gap-3 w-full overflow-hidden"}`}>
                          {/* Dynamically Scaled Icon with OnHover and OnClick micro-animations */}
                          <IconComponent className={`shrink-0 transition-all duration-200 group-hover:scale-125 group-hover:rotate-3 ${
                            isCompact ? "h-6 w-6" : "h-4 w-4"
                          } ${
                            isBaseActive 
                              ? `${modTheme.text} font-bold drop-shadow-sm scale-110` 
                              : `${modTheme.text} opacity-90 group-hover:opacity-100 group-hover:drop-shadow-xs`
                          }`} />

                          {!isCompact && (
                            <span className="flex-1 truncate transition-colors duration-150 text-inherit group-hover:font-bold">{item.label}</span>
                          )}

                          {!isCompact && item.badge && (
                            <span className={`ml-auto text-[0.625rem] font-medium px-2 py-0.5 rounded-full ${item.badgeColor || 'bg-[var(--muted)] text-[var(--muted-foreground)] border border-[var(--border)]'}`}>
                              {item.badge}
                            </span>
                          )}
                        </div>
                      </Link>

                      {/* Expand Tree Toggle chevron button right side */}
                      {!isCompact && item.subItems && (
                        <AppButton
                          variant="ghost"
                          size="icon-sm"
                          onClick={(e) => toggleTree(item.href, e)}
                          className="absolute right-2 !h-6 !w-6"
                        >
                          {isTreeExpanded ? (
                            <ChevronDown className="h-3.5 w-3.5" />
                          ) : (
                            <ChevronRightIcon className="h-3.5 w-3.5" />
                          )}
                        </AppButton>
                      )}

                      {/* Premium Interactive Module Popover Tooltip with Open Action Indicator button when minimized */}
                      {isCompact && (
                        <div className={`absolute left-full ml-2 top-1/2 -translate-y-1/2 pointer-events-none opacity-0 group-hover:opacity-100 transition-all duration-200 z-50 flex items-center gap-2 rounded-md px-2.5 py-1.5 shadow-md shrink-0 ${ "theme-card-structural text-foreground" }`}>
                          <span className="font-medium whitespace-nowrap text-xs">{item.label}</span>
                        </div>
                      )}
                    </div>

                    {/* RENDER EXPANDED SUB-ITEMS TREE CONTAINER */}
                    {!isCompact && item.subItems && isTreeExpanded && (
                      <div className={`pl-2.5 pr-1 py-1.5 space-y-1.5 relative border-l-2 ml-5 ${modTheme.border}`}>
                        {item.subItems.map((sub) => {

                          let isSubActive = pathname === sub.href;
                          if (sub.href === '/requirements/approvals' && searchParams?.get('from') === 'approvals') {
                            isSubActive = true;
                          } else if (sub.href === '/requirements' && searchParams?.get('from') === 'approvals') {
                            isSubActive = false;
                          }

                          return (
                            <Link
                              key={sub.href}
                              href={sub.href}
                              onClick={() => setClientQuery(`?scope=${sub.scopeParam}`)}
                              className={`group relative flex items-center gap-2.5 px-3 py-2 rounded-xl text-[0.8125rem] font-semibold transition-all duration-150 select-none cursor-pointer overflow-hidden ${
                                isSubActive 
                                  ? `bg-gradient-to-r to-transparent font-bold shadow-xs scale-[1.02] border ${modTheme.activeBg} ${modTheme.border} ${modTheme.text}` 
                                  : `text-muted-foreground hover:scale-[1.02] hover:shadow-xs active:scale-[0.96] border border-transparent ${modTheme.hover}`
                              }`}
                            >
                              {/* Submodule Bullet Indicator Dot */}
                              <div className={`w-1.5 h-1.5 rounded-full shrink-0 transition-all duration-200 ${
                                isSubActive 
                                  ? `shadow-xs scale-125 bg-current` 
                                  : `opacity-40 group-hover:opacity-100 group-hover:scale-125 bg-current`
                              }`} />

                              <span className="truncate flex-1 text-inherit">{sub.label}</span>
                            </Link>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
      </div>

    </aside>
    </Profiler>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { createClient } from "@/utils/supabase/client";
import { usePermissions } from "@/hooks/usePermissions";
import { AppCard, AppCardHeader, AppCardTitle, AppCardContent } from "@/components/ui/AppCard";
import { AppInput } from "@/components/ui/AppInput";
import { AppButton } from "@/components/ui/AppButton";
import { Camera, Check, Briefcase, Mail, User, Shield, Key, ChevronRight, Lock, Loader2, AlertCircle, Building, Users, ChevronDown, BadgeCheck, Building2 } from "lucide-react";
import { updateMyProfile } from "@/lib/actions/settings";

interface UserProfile {
  id: string;
  full_name: string;
  email: string;
  profile_photo: string;
  user_code: string;
  designation_id: string;
  department_id: string;
  manager_id: string;
  is_active: boolean;
  department?: { name: string } | null;
  designation?: { name: string } | null;
  role?: { name: string } | null;
  manager?: { full_name: string, profile_photo: string } | null;
}

const PRESET_AVATARS = [
  "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1527980965255-d3b416303d12?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1552058544-f2b08422138a?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1599566150163-29194dcaad36?auto=format&fit=crop&q=80&w=200",
  "https://images.unsplash.com/photo-1568602471122-7832951cc4c5?auto=format&fit=crop&q=80&w=200",
];

const getAvatarUrl = (name: string, photo?: string | null) => {
  if (photo && photo.trim() !== '') return photo;
  const seed = encodeURIComponent(name || 'User');
  return `https://api.dicebear.com/7.x/initials/svg?seed=${seed}&backgroundColor=1e293b,0f172a&textColor=ffffff`;
};

export default function UserProfileEditor() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const isSetupMode = searchParams.get('setup') === 'true';
  const supabase = createClient();
  const { roleCode } = usePermissions();
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Profile data
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);

  // Setup options (if in setup mode)
  const [departments, setDepartments] = useState<any[]>([]);
  const [designations, setDesignations] = useState<any[]>([]);
  const [managers, setManagers] = useState<any[]>([]);
  
  // Setup selections
  const [selectedDept, setSelectedDept] = useState("");
  const [selectedDesig, setSelectedDesig] = useState("");
  const [selectedManager, setSelectedManager] = useState("");
  const [isSavingOrg, setIsSavingOrg] = useState(false);
  const [managerDropdownOpen, setManagerDropdownOpen] = useState(false);
  const managerDropdownRef = useRef<HTMLDivElement>(null);

  // Form state
  const [formPhoto, setFormPhoto] = useState("");
  const [photoUploading, setPhotoUploading] = useState(false);

  // Notifications
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  useEffect(() => {
    loadUserProfile();
  }, []);

  const loadUserProfile = async () => {
    try {
      const { data: { user: authUser }, error: authError } = await supabase.auth.getUser();
      if (authError) throw new Error("Auth Error: " + authError.message);
      if (!authUser) throw new Error("No authenticated user");

      const { data, error } = await supabase
        .from("user_master")
        .select(`
          *,
          department:departments!fk_user_master_department(name),
          designation:designations!fk_user_master_designation(name),
          role:roles!fk_user_master_role(name),
          manager:manager_id(full_name, profile_photo)
        `)
        .eq("id", authUser.id)
        .single();

      if (error) {
          throw new Error(`Database Error: ${error.message}`);
      }

      setProfile(data as any);
      setFormPhoto(data.profile_photo || "");
      
      const missingDetails = !data.department_id || !data.designation_id || !data.manager_id;
      
      if (missingDetails) {
        // Fetch masters for onboarding setup
        const [deptRes, desigRes, usersRes] = await Promise.all([
          supabase.from("departments").select("id, name").eq("is_active", true).order("name"),
          supabase.from("designations").select("id, name, department_id").eq("is_active", true).order("name"),
          supabase.from("user_master").select("id, full_name, profile_photo, role_id").eq("is_active", true).neq("id", authUser.id)
        ]);
        
        if (deptRes.data) setDepartments(deptRes.data);
        if (desigRes.data) setDesignations(desigRes.data);
        if (usersRes.data) {
           const { data: roles } = await supabase.from("roles").select("id, code");
           const viewerRoleId = roles?.find(r => r.code === "VIEWER")?.id;
           setManagers(usersRes.data.filter(u => u.role_id !== viewerRoleId));
        }
      }

      setLoading(false);
    } catch (err: any) {
      console.error("Error loading profile:", err?.message || JSON.stringify(err));
      setErrorMsg(err?.message || "Failed to load profile details");
      setLoading(false);
    }
  };
  
  // Close manager dropdown on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (managerDropdownRef.current && !managerDropdownRef.current.contains(event.target as Node)) {
        setManagerDropdownOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const triggerToast = (msg: string, isError = false) => {
    if (isError) {
      setErrorMsg(msg);
      setTimeout(() => setErrorMsg(null), 3000);
    } else {
      setSuccessMsg(msg);
      setTimeout(() => setSuccessMsg(null), 3000);
    }
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith("image/")) {
      triggerToast("Only image file formats are allowed.", true);
      return;
    }

    setPhotoUploading(true);
    try {
      const { data: { user: authUser }, error: userError } = await supabase.auth.getUser();
      if (userError) throw userError;
      if (!authUser) throw new Error("Unauthenticated");

      const fileExt = file.name.split(".").pop();
      const fileName = `${authUser.id}/${Date.now()}.${fileExt}`;

      const { error: uploadError } = await supabase.storage
        .from("profiles")
        .upload(fileName, file, { cacheControl: "3600", upsert: true });

      if (uploadError) throw uploadError;

      const { data: { publicUrl } } = supabase.storage
        .from("profiles")
        .getPublicUrl(fileName);

      const res = await updateMyProfile({ profile_photo: publicUrl });
      if (!res.success) throw new Error(res.error);

      setFormPhoto(publicUrl);
      setProfile(prev => prev ? { ...prev, profile_photo: publicUrl } : null);
      triggerToast("Profile picture updated successfully!");
    } catch (err: any) {
      console.error("Upload error:", err);
      triggerToast(`Upload failed: ${err.message || err}`, true);
    } finally {
      setPhotoUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handlePresetAvatarSelect = async (avatarUrl: string) => {
    if (!profile) return;
    setPhotoUploading(true);
    try {
      const res = await updateMyProfile({ profile_photo: avatarUrl });
      if (!res.success) throw new Error(res.error);

      setFormPhoto(avatarUrl);
      setProfile(prev => prev ? { ...prev, profile_photo: avatarUrl } : null);
      triggerToast("Profile picture updated to preset!");
    } catch (err: any) {
      console.error("Update error:", err);
      triggerToast(`Update failed: ${err.message || err}`, true);
    } finally {
      setPhotoUploading(false);
    }
  };
  
  const handleCompleteSetup = async () => {
    if (!profile) return;
    if (!selectedDept || !selectedDesig || !selectedManager) {
       triggerToast("Please complete all organizational details.", true);
       return;
    }
    
    setIsSavingOrg(true);
    try {
      const res = await updateMyProfile({
        department_id: selectedDept,
        designation_id: selectedDesig,
        manager_id: selectedManager
      });
      if (!res.success) throw new Error(res.error);
      
      triggerToast("Profile setup completed successfully!");
      setTimeout(() => {
        router.push("/");
      }, 1000);
    } catch (err: any) {
      console.error("Save error:", err);
      triggerToast(err.message || "Failed to save details", true);
      setIsSavingOrg(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-20 space-y-4">
        <Loader2 className="h-8 w-8 animate-spin text-theme-icon" />
        <p className="text-sm text-muted">Loading profile data...</p>
      </div>
    );
  }

  const isMissingDetails = !profile?.department_id || !profile?.designation_id || !profile?.manager_id;
  const selectedManagerObj = managers.find(m => m.id === selectedManager);

  return (
    <div className="w-full relative">
      {/* Toast notifications */}
      {successMsg && (
        <div className="fixed bottom-6 right-6 z-[100] flex items-center gap-2 rounded-xl bg-emerald-500/90 backdrop-blur-md text-white px-5 py-3.5 shadow-2xl animate-in slide-in-from-bottom-5 duration-300">
          <Check className="h-4 w-4" />
          <span className="text-sm font-semibold">{successMsg}</span>
        </div>
      )}

      {errorMsg && (
        <div className="fixed bottom-6 right-6 z-[100] flex items-center gap-2 rounded-xl bg-rose-500/90 backdrop-blur-md text-white px-5 py-3.5 shadow-2xl animate-in slide-in-from-bottom-5 duration-300">
          <AlertCircle className="h-4 w-4" />
          <span className="text-sm font-semibold">{errorMsg}</span>
        </div>
      )}
      
      {isMissingDetails && (
